  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '1MPM G8310 & G8320 ZBV2 Diesel Gen Package .', 'Electrical & Instrument', 'PM', 'Completed', '2024-08-23', '<p><b><u>Today activity</u></b></p><p>1MPM G8310 &amp; G8320 ZBV2 Diesel Gen Package.</p><p><b><u>Action</u></b></p><p><u><b>G8310</b></u></p><p>Open Junction boxes for cleaning and re-tighten wiring termination, corrosion, clean terminals.<br>Check the AVR connection at AVR box.</p><p>Check and record generator power output.<br>Top up battery water 1 liter and clean the terminal.</p><p>      </p><p>Check battery charging system.</p><p>Test run, no alarm and working properly.<br></p><p><br><span style="background-color: rgb(255, 255, 0);"><b>Finding issue during PM on G8310</b><br>1.The buzzer was not working. The termination of the buzzer was loosen.<br>2.The manual fuel gauge is not working.&nbsp;<br><b>Action for issue 1</b><br>Tighten the termination and of the buzzer.<br>Buzzer is back to normal and working properly,<br><b>Action for issue 2</b><br>Remove the manual gauge and function test.<br>The gauge is working properly.<br>Plan to verify and TS the fuel filling system next visit.</span></p><p><u><b><br></b></u></p><p><u><b>G8320</b></u><br></p><p>Open Junction boxes for cleaning and re-tighten wiring termination, corrosion.</p><p>Check the AVR connection at AVR box.<br></p><p>Top up battery water 1 liters&nbsp;and clean terminals.</p><p>Check and record generator power output.</p><p></p><p>Check battery charging system.<br>Test run, no alarm and working properly.</p><p><br></p>', NULL, '2024-08-23 14:42:38', '2024-08-23 14:43:52', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
