-- Inserting report ID 17976
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2F-3710B Level transmitter reading error.', 'Instrument', 'CM', 'Under Monitoring', '2024-08-23', '<div>T/S 2F-3710B Level transmitter reading error.</div><div>- Removed 2LIT-31702B to clean and blow by heat gun to remove moisture inside coaxial probe.</div><div>- Installed probe back to service and tried to fine tune parameter but couldn''t success due to he alarm of&nbsp;"fiducial shift"&nbsp;was frequently active.</div><div>- Measured coaxial probe resistance of 2LIT-31702B and found it was around 71.2 K-Ohm while probe resistance of 2LIT-31700B was around 0.8 K-Ohm, suspected the probe was failure.</div><div><span style="background-color: rgb(255, 255, 0);">- Replaced 2LIT-31702B (Probe length 220 mm) with spare probe that removed from 2LIT-31715B (Probe length 156 mm) with coaxial resistance 259.5 K-Ohm.</span></div><div><div class="ewa-rteLine">- Perform fine tune parameter of 2LIT-31702B successful.</div><div class="ewa-rteLine">- Waiting to normalize process back to normal condition.</div></div>', NULL, '2024-08-23 17:31:36', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2ILIT-31700B', 'GBS-2ILIT-31700B', 'INTERFACE LEVEL INDICATOR TRANSMITTER', NULL, NULL, 'INTERFACE LEVEL INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
