  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed Monthly PM of two post car lift.', 'Mechanic', 'PM', 'Completed', '2024-08-27', '<p>Description: : Performed Monthly PM of two post car lift.</p><p><br></p><p>Working steps:</p><p>-Performed electrical isolation by emergency stop button.&nbsp;</p><p>-Checked two post mounting bolts tightness.&nbsp;(Torque 100 N-m)</p><p>-Checked cylinders (primary and secondary) for any leakage.</p><p>-Checked hydraulic hoses if any damage and leakage.</p><p>-Checked wiring sling rope condition and greasing.</p><p>-Checked mechanical locks and limit switch functional test.</p><p>-Checked arm gear if any corrosion and damage.</p><p>-Test without load and check if any abnormal noise and condition.</p><p><br></p><p>Required tools</p><p>-Torque wrench and Open wrench 30mm.</p>', NULL, '2024-08-27 15:19:34', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
