-- Inserting report ID 18154
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot fuel dispenser auto running error', 'Electrical & Instrument', 'CM', 'Waiting for Material', '2024-08-28', '<p><u><b>Today Activity</b></u></p><p>Troubleshoot fuel dispenser auto running error</p><p><u><b>Action</b></u></p><p>The dispenser didn''t stop after diesel filling. Operator inform to us.</p><p>Found the last one driver board was faulty.</p><p>Isolated the unit and checked electrical wiring.</p><p>Measured coil resistance and Insulation resistance test solenoid both units.(OK)</p><p>Checked the limit switch. (OK)</p><p>Measured motor resistance and Insulation resistance test. (OK).</p><p>Remove driver board and magnetic contactor for test at workshop.</p><p>Found one capacitor damaged at driver board.</p><p>Replace with the new capacitor.</p><p>After replacing, checked and function test driver board at workshop. (OK)</p><p>Checked and function test magnetic contactor, there is a buzzing sound.</p><p>Replaced the new magnetic contactor.</p><p>After this replacement, the diesel dispenser worked properly with one unit,<br></p><p>and the auto running error was resolved.<br>Plan to install the new board for damage one, once the spare part arrives.</p><p><u><br></u></p><p><u><b style="background-color: rgb(255, 255, 0);">History (27-08-2024)</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot fuel dispenser auto running error</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">The dispenser has two units for filling diesel and two driver boards.<br>One board was functioning properly.<br>Isolated the damaged board and installed the working board in its place.<br>After this adjustment, the diesel dispenser worked properly with one unit,<br>and the auto running error was resolved.<br>Plan to install the new board for damage one, once the spare part arrives.</span></p><p><span style="background-color: rgb(0, 255, 255);">Performer Bone/Nay/Jack</span><br><br><br></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>History(07-Aug-2024)</b></u><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot fuel dispenser auto running error.</span></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>Action</b></u><br></span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked&nbsp;<u>3100-DRV3003V70 motor driver board</u>&nbsp;condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found driver board was burned by dead lizard.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found one of socket cable was broken. (Repaired)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Need to replace new driver board for auto running error.</span><br><span style="background-color: rgb(0, 255, 255);">Performer Francis/Htet Aung/HMM</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>History(03-Aug-2024)</b><br></u>Troubleshoot fuel dispenser auto running error.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>Action</b></u><br></span></p><p><span style="background-color: rgb(255, 255, 0);">- Found some water seeping in the keypad display box.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Cleaned and checked circuit board of keypad display. (Normal condition)<br></span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked and tested limit switch of nozzle. (Working properly)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Visual checked I/O card and power board condition in control panel.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Bypassed signal of run motor.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Motor was still running after de-isolation.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Need to check power board.</span></p><p><span style="background-color: rgb(255, 255, 0);">- In progress</span><br><span style="background-color: rgb(0, 255, 255);">Performer&nbsp;Francis/Htet Aung/HMM</span></p><p><br></p>', NULL, '2024-08-28 16:26:01', '2024-08-28 18:13:50', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-A-9095', 'ATL-MS-A-9095', 'Diesel Dispenser unit', NULL, NULL, 'Diesel Dispenser unit', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8905', 'ATL-OC-A-8905', 'ZOC Diesel Dispenser unit', NULL, NULL, 'ZOC Diesel Dispenser unit', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'NL', NULL, 'EXTERNAL', '2024-08-28 16:26:01', '2024-08-28 18:13:50', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2024-08-28 16:26:01', '2024-08-28 18:13:50', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jack', NULL, 'EXTERNAL', '2024-08-28 16:26:01', '2024-08-28 18:13:50', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Elec-Tec');
