  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace fuel gas filter 2F-4120B', 'Mechanic', 'CM', 'Completed', '2024-08-29', '<p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Ensured that no pressure before perform it.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the Pressure Warning Screw and Locking Plate and contract the locking band to</p>  <p>its ''door open'' position.</p>  <p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Remove set screw retaining chain to door. Remove davit attachment bolt and lift davit arm clear door.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Opened enclosure and cleaned all parts.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Removed QOC door seal.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replaced QOC door seal and apply grease.</p><p>.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed old filter and take sample.</p><p>.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Replaced new filter element 10 ea.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Re-install locking plate and locking band.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replaced seal of pressure-warning screw.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Pressure leak test by N2 at 5 bars and by gas at 60 bar, found no leak.</p>', NULL, '2024-08-29 14:59:10', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2F-4120B', 'GBS-2F-4120B', 'FUEL GAS FILTERS/SEPARATORS UNIT B', NULL, NULL, 'FUEL GAS FILTERS/SEPARATORS UNIT B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Direk T.', NULL, 'EXTERNAL', '2024-08-29 14:59:10', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dilok T. Panot C.', NULL, 'EXTERNAL', '2024-08-29 14:59:10', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
