  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix hydraulic of starting system seeping', 'Mechanic', 'CM', 'In Progress', '2024-09-01', '<p>- Found hydraulic oil leak at seal of hydraulic manual recharge pump.</p><p>- Replaced internal part complete set, pressure leak test at 220 bar no leak was found.</p><p>- Found hydraulic leak at hydraulic auto recharge pump.</p><p>- Replaced fitting and tubing of suction discharge pump.</p><p>- Online the system found hydraulic seep from pump body.</p><p>- Plan to rectify on tomorrow.</p>', NULL, '2024-09-01 18:06:12', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL, false, 'G2N') RETURNING id INTO new_report_id;
