  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Observation of Gas Compressor Status and CCC', 'Instrument', 'OTH', 'Completed', '2024-09-01', '<div class="ewa-rteLine">Observation of Gas Compressor Status and CCC Anti-Surge Valve During CCR Decrease of Stone Wall Valve Setpoint from 120 to 110 bar</div><div class="ewa-rteLine">- During the pressure decrease to 110 bar, the fuel gas outlet scrubber temperature inceasing and observed water condense at fuel line , decided to return discharge pressure back to120 barg setpoint.</div><div class="ewa-rteLine">- The alarm 2PIT-39208 (discharge pressure low) was present on the CCC HMI.</div><div class="ewa-rteLine">- The alarm 2PIT-39708 (discharge pressure low) was also observed on the CCC HMI.</div><div class="ewa-rteLine">Confirmation with Automation verified that the last change to the alarm settings was correct.</div><div class="ewa-rteLine">- Upon investigation, it was determined that the alarm setting must be adjusted on the CCC controller.</div><div class="ewa-rteLine">- Consultation with EMI is needed to determine if we can change the value ourselves.</div>', NULL, '2024-09-01 18:18:20', '2024-09-04 16:03:22', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\TasapornV', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-CCC-UCP.SPK', 'GBS-CCC-UCP.SPK', 'CCC CONTROL SYSTEM', NULL, NULL, 'CCC CONTROL SYSTEM', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Wiwat', NULL, 'EXTERNAL', '2024-09-01 18:18:20', '2024-09-04 16:03:22', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\TasapornV');
