-- Inserting report ID 18275
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify protection Enclosure temperature TC2', 'Instrument', 'CM', 'In Progress', '2024-09-01', '<div class="ewa-rteLine">Verify protection logic of Enclosure temperature spread TC2</div><div class="ewa-rteLine">Reference to TC#2 Enclosure Temperature Validation Logic.</div><div class="ewa-rteLine">We have two temperature element sensors. the function block must make a decision to use the correct enclosure temperature value based on the following conditions:</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">1. If both sensors are healthy, the selected value will be the average of the two.</div><div class="ewa-rteLine">2. If one sensor fails, the selected value will be the healthy sensor''s value.</div><div class="ewa-rteLine">3. If the difference between the two sensors exceeds 63.0°F for more than 60 seconds, </div><div class="ewa-rteLine">    the selected value will be the maximum healthy value, and the standby enclosure fan will be activated.</div><div class="ewa-rteLine">4. If both sensors fail, the selected value will default to 9999, triggering a high-high (HH) alarm, and the unit         will decelerate to minimum load.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">Need to verify more cause and effect.</div>', NULL, '2024-09-01 18:20:05', '2024-09-04 16:01:47', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\TasapornV', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-3300.PK', 'GBS-2X-3300.PK', 'PPS GAS COMPRESSION TRAIN 2', NULL, NULL, 'PPS GAS COMPRESSION TRAIN 2', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Wiwat', NULL, 'EXTERNAL', '2024-09-01 18:20:05', '2024-09-04 16:01:47', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\TasapornV');
END $$;

