  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S ASCV FV-39721 fail to control.', 'Instrument', 'CM', 'Completed', '2024-09-04', '<p>- Information from CCR ,The TC#2 ASCV was open 100% and cannot command to local actuator.</p><p>- TC#2 not trip gas of export comp was circulate.</p><p>- Performed to check at local found solenoid valve SY-39721 was abnormal air passing to vent port.</p><p>- Performed to replace new SY-39721 on ASCV during loss air supply condition.</p><p>&nbsp; &nbsp; - Function test of SY-39721 was OK ,Then found Quick exhaust valve indicator broken and air leak on broken point.</p><p>- Performed to replace Quick exhaust valve and function test ,valve can service back to normal.</p><p>- ASCV can operate and TC#2 was back to normal.</p>', '<p>-&nbsp;<span style="font-size: 14px;">Quick exhaust valve was replace old model and install on PSD 2023.</span></p><p><span style="font-size: 14px;">- the indicator are plastic material it''s the weak point of ASCV may we need to change to another model for improve the life times service.&nbsp; &nbsp;</span></p>', '2024-09-05 14:36:08', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL, false, 'G2S') RETURNING id INTO new_report_id;
