  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '12MPM G8930 Day 2', 'Electrical & Instrument', 'PM', 'In Progress', '2024-09-06', '<p><u><b>Today Activity</b></u></p><p>12MPM G8930 Gas Engine Gen Package 1 Day 2<br></p><p><u><b>Action</b></u></p><p>Measure the insulation resistance value of the (IR) stator winding (500V).<br>Measure the resistance value (R) of the stator winding.<br>Measure the insulation resistance value of the (IR) anti condensation heater (500V).<br></p><p>Measure the resistance value (R) of the anti condensation heater.</p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>History(05-09-2024)</u></b><br></span></p><p><span style="background-color: rgb(255, 255, 0);">12M PM G8930 Gas Engine Gen Package 1 Day 1<br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);"> Open Junction boxes for cleaning and re-tighten wiring termination, corrosion<br>Measure insulation resistance (IR) of Radiator Fan#1 and Fan#2 Motor winding at 500V.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Measure resistance value (R) of Radiator Fan#1 and Fan#2 motor winding.<br>Measure insulation resistance (IR) of Radiator Fan#1 and Fan#2 Heaters at 500V.</span></p><p><span style="background-color: rgb(255, 255, 0);">Measure resistance value (R) of Radiator Fan#1 and Fan#2 Heaters.<br>Grease the Radiator Fan#1 and Fan#2.<br>Measure insulation resistance (IR) of Exhaust Fan#1 and&nbsp;Fan#2 Motor winding at 500V.<br>Measure resistance value (R) of Exhaust Fan#1 and&nbsp;Fan#2 motor winding.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Measure insulation resistance (IR) of water jack 1 and 2 heater at 500V.</span></p><p><span style="background-color: rgb(255, 255, 0);">Measure resistance value (R) of water jack 1 and 2 heater at 500V.</span></p>', NULL, '2024-09-06 17:34:40', '2024-09-27 18:14:57', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
