  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-P-8220.PK', 'GBN-P-8220.PK', 'SPP DIESEL FIRE WATER PUMP PACKAGE', NULL, NULL, 'SPP DIESEL FIRE WATER PUMP PACKAGE', 'GBN-SPP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
