  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S QPS Fire water pump cannot start by electric', 'Electrical', 'CM', 'Completed', '2024-09-09', '<p>T/S QPS Fire water pump cannot start by electric mode.</p><p>- Perform cleaning starter motor and solenoid done, found the solenoid insulation @&gt;55 MOhm.</p><p>- Found the starter motor insulation @0.13 MOhm.</p><p>- Perform simulate running tested starter motor done, found the motor working properly.</p><p>- Perform assembled and re-installed starter motor 2DM-6201 done.</p><p>- Perform FWP runnig test, found the CB of starter motor solenoid current @20.3 Amp. (CB13 Amp)</p><p>- Perform unit running tested by Electric start, found the unit running properly.</p>', '<span style="color: rgb(85, 85, 85); font-family: Tahoma; font-size: 14px;">To be order ELECTRIC MOTOR STARTER,P/N.338-3454, Item No.&nbsp;</span><span style="color: rgb(85, 85, 85); font-family: Tahoma; font-size: 14px;">19.09.45.813.3</span>', '2024-09-09 18:21:59', '2024-09-09 18:28:01', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
