-- Inserting report ID 18612
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify G8930 high temp SD alarm ', 'Electrical & Instrument', 'CM', 'Completed', '2024-09-10', '<p></p><p></p><p><b><u>Today’s Activity</u></b></p><p>Verify the G8930 high-temperature SD alarm.</p><p><b><u>Action Taken</u></b><br></p><p>Measure RTD Sensor Temperature by using YOKOGAWA multimeter calibrator CA150.</p><p>Sensor Readings:</p><p>&nbsp; &nbsp; &nbsp;- Sensor 1: 36.1 °C, 114.2 Ohm</p><p>&nbsp; &nbsp; &nbsp;- Sensor 2: 36.1 °C, 114.2 Ohm</p><p>&nbsp; &nbsp; &nbsp;- Sensor 3: 36.1 °C, 114.2 Ohm</p><p>&nbsp; &nbsp; &nbsp;- Sensor 4: 36.1 °C, 114.2 Ohm</p><p>All sensors are functioning correctly.</p><p><br></p><p><b><u>Issue Identified:</u></b><br>Noticed a 20 °C discrepancy between the actual temperature and the temperature displayed on the programmable LED indicator.<br></p><p><br><b><u>Action Taken to Resolve Issue:</u></b><br></p><p>Inspected the indicator terminal connections.</p><p>Recut and reshaped the wires, then reinstalled them.</p><p>Temperature readings are now consistent.<br></p><p>G8930 is operating properly.</p><p>Plan to test run during the upcoming weekly test run.<br></p>', NULL, '2024-09-10 14:24:06', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Elec-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930-PACK', 'ATL-OC-G-8930-PACK', 'Gen, ZOC Gas Generator Package 3', NULL, NULL, 'Gen, ZOC Gas Generator Package 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2024-09-10 14:24:06', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Elec-Tec', NULL);
