  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2P-4320C Pump replacement.', 'Mechanic', 'CM', 'In Progress', '2024-09-12', '<p>- Pump replacement due to bearing vibration high.</p><p>- Drain bearing lube oil.</p><p>- Remove pump accessory.</p><p>- Remove pump coupling.</p><p>- Remove pump from pump volute found.</p><p>- Check pump volute condition found normal and check volute wearing ring dimension found 191.88 mm (normal).</p><p>- Clean pump volute and preserve all parts.</p><p>- Pre-check new pump then install pump to pump volute.</p><p>- Tighten nut with torque wrench at 293 Nm.</p><p>- Replace pump lube oil with Mobile 625.</p><p>- Install all pump accessory.</p><p>- Request to process de-isolation for leak test found no leakage.</p><p>- House keeping the working area.</p><p>- Continue to hot alignment in the next day.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>&nbsp;&nbsp;</p>', 'Z:\\Department Share\\03 Maintenance\\031 DBS_MM\\6. Picture\\61. PPS Equipment Picture\\All pumps\\2P-4320 Heating Medium pumps\\2P-4320 C\\2024\\2024.09.12 2P-4320C pump replacement due to bearing vibration high', '2024-09-12 18:18:38', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
