  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2G-1540B Shut down @ WPS05', 'Instrument', 'CM', 'Completed', '2024-09-14', '<p>T/S 2G-1540B Shut down @ WPS05 in below details.</p><p>-Performed as found checked found TEG "A" was still running with 8.0 A with 5A of Batt discharge while TEG "B"was Shut down.</p><p>-Restarted TEG''B" and open JB to check and pull for any loose&nbsp; cable of all terminals then TEG was immediately tripped.</p><p>-Found the cable of pressure switch was almost broken then cut and reterminated .</p><p>-Restarted TEG"B" then set up out put voltage of both TEGs 27.9 Vdc for "A" and 27.5for "B"</p><p>-Put Both TEGs in service then measure the output voltage 25.9 Vdc for "A" and 26.1 for "B".supply current 5 A for "A" and 15 A for "B".with 3 A of battery charging current on HMI screen.</p><p><br></p><p><br></p>', NULL, '2024-09-14 16:31:55', '2024-09-15 06:42:35', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
