  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Wirote', NULL, 'EXTERNAL', '2024-09-14 16:31:55', '2024-09-15 06:42:35', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
