  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '12M PM for Gas Generator G-9115', 'Electrical & Instrument', 'PM ', 'In Progress', '2024-09-15', '<p><span style="background-color: rgb(255, 255, 0);"><b>Perform 12M PM for Gas Generator G-9115.(Day-1)</b></span></p><p>1.Check and Measure Insulation Resistance (IR) value for Main Stator Winding.</p><p>T1+ E = 166M Ohm.</p><p>T2+ E = 153M Ohm.</p><p>T3 + E =822M Ohm.</p><p>2.Check and Measure Resistance(R) value for Main Stator Winding.</p><p>T1 + T2 = 11 m Ohm</p><p>T2 + T3 = 7.5 m Ohm</p><p>T1 + T3 = 12 m Ohm</p><p>3.Check and Measure Insulation Resistance (IR) value for Main Power Cable.</p><p>T1 + E = 1.45M Ohm</p><p>T2 + E = 1.42M Ohm</p><p>T3 + E = 1.41M Ohm</p><p>N + E = 1.41M Ohm</p><p>4.Check and Measure Insulation Resistance (IR) value for Permanent Magnet Generator(PMG) Winding.</p><p>T1 + E = 3.46G Ohm</p><p>T2 + E = 5.32G Ohm</p><p>T3 + E = 6.61G Ohm</p><p>5.Check and Measure Resistance (R) value for Permanent Magnet Generator(PMG) Winding.</p><p>PMA1 + PMA2 = 2.1 Ohm</p><p>PMA2 + PMA3 = 2.2 Ohm</p><p>PMA1 + PMA3 = 2.3 Ohm</p><p>6.Check and Measure Insulation Resistance (IR) value for Exciter Stator Winding.</p><p>EF1 + E = 13.9M Ohm</p><p>EF2 + E = 13.0M Ohm</p><p>7.Check and Measure Resistance (R) value for Exciter Stator Winding.</p><p>EF1 + EF2 is 12.3 Ohm.</p>', NULL, '2024-09-15 18:31:42', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2024-09-15 18:31:42', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL);
