  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2MPM of instrument air compressor A unit.', 'Mechanic', 'PM ', 'Completed', '2024-09-04', '<div>Job Description : 2MPM on instrument air compressor A unit.</div><div><br></div><div>Job Steps :</div><div><br></div><div><p>- Perform electrical isolation and process isolation.</p><p>- Check and clean the air filter.</p><p>- Drain and top up compressor oil 4L.</p><p>- Check the alignment and belts tension.</p><p>- Check the mounting bolts tension.</p><p>- Remove the intercooler connection.</p><p>- Replace the new connection.</p><p>- Perform electrical deisolation.</p><p>- Test run and check the leak from connection of intercooler. (No Leak).</p><p>- Housekeeping the compressor package</p></div>', NULL, '2024-09-16 09:38:14', '2024-09-16 09:38:32', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech', false, 'ATL') RETURNING id INTO new_report_id;
