  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/STG#1 cannot start by liquid', 'Turbine E&I', 'CM', 'In Progress', '2024-09-15', '<div>Troubleshooting TG#1 cannot start by fuel liquid mode.</div><div>- Stroking test liquid fuel valve ELF344 found valve&nbsp; command and feed back was normaly. Error at command 0%. Feed back reading 1.5%.</div><div>- Tried to configulation KT_liq_Light_step from 0.55 to 0.7. Refer mail form Vendor. Found still start fail. Then change back to 0.55</div><div>- Tried to configulation KT_Liq_Ltoff_Fuel_Limit from 2.75 to 3. Found start fail.</div><div>- Start test by gas fuel mode. Found alarm liquid purge fail.</div><div>- Tried stoking test liquid purge valve found normally.</div><div>- During unit nearly ready to load. In sequence of liquid purge. Found pressure transmitter of liquid purge was HI-HI then tripped unit.</div><div>To be verify transmitter.</div>', NULL, '2024-09-16 16:05:14', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6100-DF', 'ART-A-6100-DF', 'DUAL FUEL SYSTEM', NULL, NULL, 'DUAL FUEL SYSTEM', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Piriyut K. \\ Phithak S.', NULL, 'EXTERNAL', '2024-09-16 16:05:14', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL);
