-- Inserting report ID 18933
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform Crank soak Wash', 'Turbine Mech', 'PM', 'Completed', '2024-09-16', '<p>Perform Crank Soak Wash SGC#1 (Unit Running Hours 26384 Hrs.)<br></p><p>- Stopped SGC#1 @ 06:00<br>- Mos UA-1618, UA-1619 Confirm Gas, Confirm Fire by CCR As PTW Required<br>- Mos PIT-4241 Fuel gas pressure. TIT-4212 Fuel gas temperature by CCR As PTW Required<br>- Perform Process Isolation Fuel gas inlet valve 1 point.<br>- Confirm Gas starter inlet valve is open.<br>- Perform open PTW at work site SGC#1.<br>- Inhibit CO2 As PTW Required<br>- Open SGC#1 enclosure door.<br>- Check T5 AVG Temperature not exceed 65’C if temperature is over than 65’C should be manual crank for cool down.</p><p>On Crank Wash Step (Zok 2 Time / Water wash 3 Time)</p><p>1. Water wash preparation ZOK27 Q’ty = 20 liters. Deionized water 80 liters / Cycle</p><p>&nbsp; &nbsp; &nbsp;(ZOK27 2 Pail / Deionized 23 Pails)&nbsp;&nbsp;<br>2. Removed air inlet side cover for observe water spray.<br>3. Insert spade into gas fuel manifold.<br>4. Disconnected fuel line and spark plug at torch.<br>5. Removed 11th stage bleed manifold both side and installed blinds.<br>6. Connected Utility air supply to No.1 bearing pressure 30 psi.<br>6. Disconnected combustion drain line and put drain line to outside.<br>7. Connected wash water from cart to potable on crank clean to package.<br>8. Started on crank at HMI LER wait NGP until 15-16 %.<br>9. Activated wash water to spray water to inlet engine.<br>10. Repeat Step 8 and 9 total 2 times and soak about 30 min.<br>11. Cleaned wash cart with deionized water.<br>12. Fill 100 liters deionized water for water rinse washing. Repeat Step 8 and 9 total 3 times.<br>13. Removed drain plug at torch and perform cranking dry by repeat step 8 about 10 minute for removing rest water inside engine<br>14. Re-installed all component parts back to original. (110 Ft.lb for bolt of stage 11th bleed manifold).</p><p>15. Closed PTW and Process De-isolation .<br>16. Start up unit for Fire dry and continue on load for duty</p>', '<p>ToolsList.</p><p>- Wrench 9/16”, 11/16”, 13/16”, 3/4”, 5/8”, 7/8”</p><p>
- Torque wrench (value 110 ft/lbs)<br><br></p><p>Spare parts:</p><p>- O-ring: Item 20.70.00.379.3 = 1 ea</p><p>- Spark plug: Item 20.70.00.131.3 = 1ea</p><p>- Gasket: Item 20.70.00.154.3 = 2 ea&nbsp;</p><p>- ZOK-27: Item 87.11.50.001.9 = 40 Liters (2 pails)</p><p>- Distilled water: Item 87.16.75.001.9 = 460 Liters. (23 pails)&nbsp;</p>', '2024-09-16 18:45:22', '2024-09-17 15:33:35', 'PTTEP\\Art.MechTurbine', 'PTTEP\\TasapornV', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-1610', 'ART-A-1610', 'SALES GAS COMPRESSION TRAIN 1', NULL, NULL, 'SALES GAS COMPRESSION TRAIN 1', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pichet Th.', NULL, 'EXTERNAL', '2024-09-16 18:45:22', '2024-09-17 15:33:35', 'PTTEP\\Art.MechTurbine', 'PTTEP\\TasapornV');
