  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet Aung', NULL, 'EXTERNAL', '2024-09-17 18:03:31', '2024-09-17 18:07:15', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
