-- Inserting report ID 18954
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix LOPC seeping point at BDV-82010 at MOGE line', 'Electrical & Instrument', 'CM', 'Completed', '2024-09-17', '<p><u><b>Today Activity</b></u></p><p>Fix LOPC seeping at BDV-82010.</p><p><br></p><p><u><b>Action</b></u></p><p>-Prepared work permit.</p><p>-Process isolation done by OPT.</p><p>-Checked BDV-82010 on site condition.</p><p>-Found that gas leak from accumulator blind plug and released vent plug as well.</p><p>-De-pressurized the BDV accumulator tank.</p><p>-Removed and check the blind plug of the accumulator, and released vent plug.</p><p>-Found that teflon tape on plug of accumulator are aging and vent plug thread are dent.</p><p>-Rewind the tape on plug and reconnected back to BDV accumulator.</p><p>-Modified the vent plug thread with file and reconnected to accumulator.</p><p>-De-isolated the process and pressurized on BDV.</p><p>-Check the leak test with snoop liquid.&nbsp;</p><p>-Back to normal state/ No gas leakage (Complete)</p>', NULL, '2024-09-17 18:08:22', '2024-09-17 18:23:21', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-BDV-82010', 'ATL-OC-BDV-82010', 'BDV Outlet to MOGE station', NULL, NULL, 'BDV Outlet to MOGE station', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
