-- Inserting report ID 19040
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Air compressor unit A power failure', 'Electrical & Instrument', 'CM', 'Completed', '2024-09-20', '<p><b><u>Today Activity&nbsp;</u></b></p><p>Troubleshoot Air compressor unit A power failure</p><p><b><u>Action</u></b></p><p>-Isolated IA compressor A</p><p>-Checked MCCB contacts condition.</p><p>-Found insect (wasp) nest in motor terminal box.</p><p>-Clean and isolated cable gland hole of motor terminal box.</p><p>-Performed insulation testing for air compressor motor. (normal)</p><p>- All values of results are &gt; 220 M ohm.</p><p>-Measured air compressor winding.(0.7 ohm, 0.7 ohm, 0.9 ohm)<br></p><p>-Performed de-isolation and test run</p><p>-Back to normal, and run in normal state. (Still monitoring).</p><p><br></p><p><u><b style="background-color: rgb(255, 255, 0);">History(16-Sep-2024)</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Adjustment of Air compressor unit A pressure switch&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">-Check the pressure switch condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Found that Lagging unit is operated 7.0 bar start and 8.0 bar stop</span></p><p><span style="background-color: rgb(255, 255, 0);">-Adjusted lag pressure switch 7.3 start , 8.5 bar stop as per operation team requirement.<br><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">History(13-Sep-2024)</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Alarm fault IA air compressor phase monitoring relay.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">-Verify Air compressor control panel.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Found that PH A relay fault alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Reset the relay.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Back to normal (complete)</span></p>', NULL, '2024-09-20 14:36:12', '2024-12-29 13:26:18', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8980A', 'ATL-OC-A-8980A', 'ZOC IA Compressor A', NULL, NULL, 'ZOC IA Compressor A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet Aung', NULL, 'EXTERNAL', '2024-09-20 14:36:12', '2024-12-29 13:26:18', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jack', NULL, 'EXTERNAL', '2024-09-20 14:36:12', '2024-12-29 13:26:18', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec');
