  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, ' 2HCV-14000D Replace internal parts', 'Mechanic', 'CM', 'Completed', '2024-09-22', '<p align="left">- 2HCV-14000D Replace internal parts.</p><p align="left">- After remove stepping actuator and bonnet found damage of flow ring and nozzle.</p><p align="left">- Replace Seat (25042-010), Nozzle (25358-003)</p><p align="left">- Replace Teflon seal P/N: 93233 and P/N: 93227 on seat and nozzle.</p><p align="left">- Place nozzle and seat on seal surface at outlet port by direct the hole on nozzle to inlet port.</p><p align="left">- Replace metal seal: Bonnet-Body P/N: 25072-002</p><p align="left">- Replace bonnet with overhauled internal part.</p><p align="left">-&nbsp;Torque hex cap bonnet-valve body 5/8” at 84 ft-lb.</p><p align="left">- Install mounting plate and stepping actuator.</p><p align="left">- Test leak at bonnet joint and passing.</p><p align="left">- Closed choke valve by manual, open wing valve&nbsp;</p><p align="left">- Release pressure downstream of choke valve to “zero”&nbsp;</p><p align="left">- Shut in pressure 90.5 bar, downstream 0.5 bar, No passing (acceptable) and no external leak.</p><p align="left">- Calibrate choke valve by MEI.</p><p align="left">- Choke valve “D” is normal operation</p><p align="left"><br></p><div><br></div>', NULL, '2024-09-23 09:08:35', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2HCV-14000D', 'GBS-2HCV-14000D', 'CHOKE VALVE', NULL, NULL, 'CHOKE VALVE', 'GBS-WP04', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
