-- Inserting report ID 19163
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S new GCAU installation problem in 2UPS-5701A/B', 'Electrical', 'CM', 'Completed', '2024-09-23', '<div>T/S new GCAU installation problem in 2UPS-5701A/B. (Since 22-Sep-2024)</div><div><br></div><div>23-Sep 2024: Calibrate DC UPS parameter</div><div>23-Sep-2024: AEG provides Preliminary Technical Investigation Report</div><div><div><p><br></p><p>After the close-out meeting, the Way forward for this issue shall be</p><p>1. Short-term Solution</p>  <div class="O1">- The original GCAU card has been reinstalled and successfully calibrated to the VAC nominal voltage and other parameters.</div>  <div class="O1">- The old GCAU from 2UPS-5703B is configured as a hot spare for 2UPS-5701A/B. In the event of a GCAU card failure in 2UPS-5701A/B, GBS will install the configured card and recalibrate the parameters.</div>  <div class="O1"><br></div>  <p>2. Long-term Solution</p>  <div class="O1">- AEG Thailand will contact global support regarding the insufficient VA rating of transformer T11, which may not adequately support the new GCAU card. </div>  <div class="O1">- SMD request may be required if AEG''s proposed solution necessitates revisions to the drawing</div></div></div>', NULL, '2024-09-23 17:54:14', '2024-09-23 20:38:06', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\WeerayaS', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2UPS-5701A', 'GBS-2UPS-5701A', '24VDC 28.8KW,INPUT MAX.UPS(FEEDER A)', NULL, NULL, '24VDC 28.8KW,INPUT MAX.UPS(FEEDER A)', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
