-- Inserting report ID 19170
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-23 T/S G-10340B TEG  unit tripped', 'Instrument', 'CM', 'Complete', '2024-09-23', '<p>T/S G-10340B TEG (500W)</p><p>Found a problem</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1.Ignition board&nbsp;overheat causes the insulation to melt.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2.Cable Pressure switch&nbsp;Rust causes wires to break.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3.The nut at the terminal is rusty, causing the nut to become loose.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 4.CUBE timer is cracked.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 5.Battery not power.</p><p>Action:&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1.Replace Ignition board ( Item : 65.34.10.013.3 )</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2.Cut and replace wires and cable lux.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3.Replace new terminal.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 4.Replace CUBE timer and set timer 40 sec ( Item : 65.34.10.103.3 )</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 5.Replace battery&nbsp; ( Item : 65.34.10.102.3)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;7.Replace Pressure switch ( Item : 65.34.10.031.3 )</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;8.Replace Them couple ( item : 65.34.10.049.3)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p><br></p><p><br></p>', 'G:\\Selective Access\\02-PBN-M\\02 MEI\\19 Photos\\01 Instrument Photos\\13-All Picture\\01.All Wellhead Remote platform\\WP23\\TEG\\TEG-B&nbsp; TS (23-09-2024)', '2024-09-23 18:43:54', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Inst-Lead', NULL, false, 'G2N') RETURNING id INTO new_report_id;
