-- Inserting report ID 19226
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace CO2 Membrane element T2B1', 'Mechanic', 'PM', 'Completed', '2024-09-25', '<p>&nbsp;= Production request to CO2 membrance element replacement 12 tubes.</p><p><br></p><p>On 23 September 2024.</p><p><br></p><p>1. Tool and lifting gear preparation.</p><p>2. Remove pipe elbow and nozzle of tube # 12. (Wrench # 36 mm.)</p><p>3. Remove old element 12 tubes. North 6 ea. and South 6 ea.</p><p>4. Replace new CO2 membrane element.</p><p>&nbsp; &nbsp; 4.1 Replace O-RING,VITON,2",UOP,P/N.62653 = 14 ea.</p><p>&nbsp; &nbsp; 4.2 Replace&nbsp;GASKET,SPW,316L/GRA,IR:316L,CS,#600,4" = 4 ea.</p><p>&nbsp; &nbsp; 4.3 Replace&nbsp;CENTERING RING, <a href="PN:62650">PN:62650</a>&nbsp;(Reuse) = 14 ea.</p><p>&nbsp; &nbsp; 4.4 Replace clamp lock center ring (Reuse) = 14 ea.</p><p>&nbsp; &nbsp; 4.5 Replace&nbsp;TAPER LOK SEAL RING,UOP,P/N.88983-000 = 2 ea.</p><p>&nbsp; &nbsp; 4.6 Replace check valve&nbsp;Part number: 88982-000 = 2 ea.</p><p>5. Reinstall nozzle and pipe elbow.</p><p>6. Apply JIMS. Torque 242 ft.lb.</p><p>7. Housekeeping.</p><p>8. Production inform CO2 membrance element inccorect.</p><p><br></p><p>On 24 September 2024.</p><p>1. Tool and lifting gear preparation.</p><p>2. Remove pipe elbow and nozzle of tube # 12. (Wrench # 36 mm.)</p><p>3. Remove old element 12 tubes. North 6 ea. and South 6 ea.</p><p>4. Replace new CO2 membrane element.</p><p>&nbsp; &nbsp; 4.1 Replace O-RING,VITON,2",UOP,P/N.62653 (Reuse)</p><p>&nbsp; &nbsp; 4.2 Replace&nbsp;GASKET,SPW,316L/GRA,IR:316L,CS,#600,4" = 4 ea.</p><p>&nbsp; &nbsp; 4.3 Replace&nbsp;CENTERING RING,&nbsp;<a href="pn:62650">PN:62650</a>&nbsp;(Reuse) = 14 ea.</p><p>&nbsp; &nbsp; 4.4 Replace clamp lock center ring (Reuse) = 14 ea.</p><p>&nbsp; &nbsp; 4.5 Replace&nbsp;TAPER LOK SEAL RING,UOP,P/N.88983-000 = 2 ea.</p><p>&nbsp; &nbsp; 4.6 Replace check valve&nbsp;Part number: 88982-000 (Reuse)</p><p>5. Reinstall nozzle and pipe elbow.</p><p>6. Apply JIMS. Torque 242 ft.lb.</p><p>7. Housekeeping.</p><p>8. Pressure leak test and not found leak.</p>', '<p>S/N of CO2 membrane element, production record new part.</p><p><br></p><p>Check valve&nbsp;Part number: 88982-000 (Reuse) = 2 ea.&nbsp; &nbsp; &nbsp; &nbsp;MESC:43.50.10.002.3</p><p>CENTERING RING, <a href="PN:62650">PN:62650</a>&nbsp;(Reuse) = 14 ea.&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;MESC :43.50.10.001.3</p><p>Clamp lock center ring (Reuse) = 14 ea.</p><p>TAPER LOK SEAL RING,UOP,P/N.88983-000 = 4 ea.&nbsp; &nbsp; &nbsp; MESC:&nbsp;43.50.10.012.3</p><p>O-RING,VITON,2",UOP,P/N.62653 = 14&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; MESC: 43.50.10.009.3</p><p>GASKET,SPW,316L/GRA,IR:316L,CS,#600,4" = 8 ea.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; MESC:&nbsp;85.41.36.420.1<br></p><p><br></p>', '2024-09-25 18:40:40', '2024-09-25 18:48:37', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-MEM-2400-01-12', 'ART-MEM-2400-01-12', 'MEMBRANE BANK 1', NULL, NULL, 'MEMBRANE BANK 1', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pawaris', NULL, 'EXTERNAL', '2024-09-25 18:40:40', '2024-09-25 18:48:37', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thavit', NULL, 'EXTERNAL', '2024-09-25 18:40:40', '2024-09-25 18:48:37', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Suthus', NULL, 'EXTERNAL', '2024-09-25 18:40:40', '2024-09-25 18:48:37', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
