  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot lube oil high temp shutdown', 'Mechanic', 'CM ', 'Completed', '2024-09-23', '<p>- Generator trip by high lube oil high temp.</p><p>- Check the coolant level.</p><p>- Top up coolant 13 liters.</p><p>- Check the lube oil temperature sensor of bank A and B.</p><p>- Found bank B lube oil temperature connection was broken.</p><p>- Found bank A lube oil temperature was wrong sensor.</p><p>- Swap the both lube oil temperature with G-9110.</p><p>- Test run and check the leakage.</p><p>- Changeover duty from G-9125.</p>', NULL, '2024-09-25 19:11:26', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
