  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG-5610, Replaced defective hydraulic starter', 'Mechanic', 'CM', 'Complete', '2024-09-23', '<ul type="disc">  <li><b>TG-5610</b>, Unit      replaced defective hydraulic starter motor by claim spare part with SOLAR.</li></ul><ul type="disc">  <li>- Removed the old hydraulic starter motor and replaced hydraulic starter motor with new one.</li><li>- Starting      was tested in crank mode, as it was found that the new hydraulic starter      motor did not rotate and the Engine NGP was 0%.</li>  <li>- Starting      was tested in crank mode about 3 times, but the result was still the same.</li>  <li>- The new      hydraulic starter motor is unserviceable.</li>  <li>- Replaced      hydraulic starter motor with the old one and reinstalled it.</li>  <li>- Unit      started and loaded at 19:20 hrs., R/H. 8,676 hrs.</li></ul><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Information, Observed during cranking test activities on 23 Sep 2024</span></p><p>-&nbsp;&nbsp;&nbsp;Starting was tested in crank mode, as it was found that the new hydraulic starter motor did not rotate and the Engine NGP was 0%.</p><p>-&nbsp;&nbsp;&nbsp;Starting was tested in crank mode about 3 times, but the result was still the same.</p><p>-&nbsp;&nbsp;&nbsp;Hydraulic supply pressure builds up to 150 Kpag, then reduces to 80 Kpag, maintaining constant pressure until the unit fails to start.</p><p>        </p><p>-&nbsp;&nbsp;&nbsp;The indicator of the new hydraulic starter motor moves to the opposite side with the old hydraulic starter motor.</p><ul type="disc"> </ul><ul type="disc"> </ul>', NULL, '2024-09-25 19:42:59', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.turbine-Mech', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TG-5610', 'GBN-TG-5610', 'TURBO GENERATOR 1 PACKAGE', NULL, NULL, 'TURBO GENERATOR 1 PACKAGE', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Numchoke P.', NULL, 'EXTERNAL', '2024-09-25 19:42:59', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.turbine-Mech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Teerayut C.', NULL, 'EXTERNAL', '2024-09-25 19:42:59', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.turbine-Mech', NULL);
