  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform PM Lube oil cooler fan (During 8K PM)', 'Turbine Mech', 'PM', 'Completed', '2024-09-25', '<p>- Performed Electrical isolation BM-6120 at Switch gear room.<br>- General inspection Lube oil cooler fan package.<br>- As found belt tension and alignment<br>- Replaced cooler fan belt, check belt tension and realignment.<br>- Injected grease to cooler fan shaft bearings.<br>- Retighten cooler fan blade fitting bolts.<br>- Retighten motor mounting bolts.<br>- Cleaning cooler package , fan blade and shaft.<br><br>SKF Belt Frequency tool setting.<br>Belt type: 3VX-800<br>Small pulley Dia. = 130 mm.<br>Speed range = 1445 RPM / Min<br>Span Length (M.)= 0.620 M.<br>Belt tension per single belt<br>Mass Single belt = 0.076 kg/m<br>Belt tension target 469 Newton (New belt)</p><p><br></p><p>Tool<br>- Combination Wrench 11/16 ,1" 1/16 ,15/16<br>- Allen key 1/4 , 1/8<br>- Flat Crew driver<br>- Belt Alingment<br>- Belt frequency.<br>- Grease Gun<br>- Grease EP-2<br></p>', NULL, '2024-09-27 13:11:25', '2024-10-01 16:31:00', 'PTTEP\\Art.MechTurbine', 'PTTEP\\Art.MechTurbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-B-6120', 'ART-B-6120', 'OIL COOLER FAN', NULL, NULL, 'OIL COOLER FAN', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
