-- Inserting report ID 19270
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS ventilation fan 2 at ZBV1', 'Electrical & Instrument', 'CM', 'Waiting for Material', '2024-09-27', '<p><b><u>Today activity</u></b></p><p>Replace the contact of the ventilation fan 2 at ZBV1.<br><b><u>Action 1</u></b></p><p>Replace the new arrival spare contactor from the PMO/I.</p><p>Replace all three contactors of Vent Fan 2, as the fan cannot start.<br><b><u>Action 2</u></b></p><p>Performed insulation resistance testing on cables "L," "N," and "G." All readings were normal, exceeding 100 MO.<br></p><p>Identified that 2 contactors of the magnetic contactor are damaged and needs replacement. (No spare available).</p><p>Plan to order spare part.</p><p><br></p><p><b style="font-size: 15px;"><u>History (11-Nov-2023)</u></b><br></p><p><span style="background-color: rgb(255, 255, 0);">ventilation fun of - Follow up the ventilation fan malfunction as per report (Handover) on 18 Oct 2023.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">- Replaced the new power cable as per mention in the report. after replaced the ventilation still can''t run and voltage output drop measurement with connect load is 147 Vac. and disconnect load&nbsp; 203 Vac.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Performed the insulation resistance testing the cable&nbsp; "L" and "N" and "G" all are normal condition. &gt;&gt; more than 100 M-Ohm.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Swap the ventilation fan controller(Magnetic contactor) by </span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; - the Ventilation fan no.1 use the Magnetic contactor no.2 &gt;&gt; Ventilation fan no.1 can''t start.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp; - the Ventilation fan no.2 use the Magnetic contactor no.1 &gt;&gt; Ventilation fan no.2 can run as normal.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Suspect the Magnetic contactor for ventilation no.2 abnormal condition need to deeply verify.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Prepare the drawing and plan to T/S again soon&nbsp;<br><br>By Anon/Alan</span></p>', NULL, '2024-09-27 16:06:19', '2024-09-27 16:07:25', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-VENTILATION-FAN-2', 'ATL-BV1-VENTILATION-FAN-2', 'FAN, ZBV1 VENTILATION FAN 2', NULL, NULL, 'FAN, ZBV1 VENTILATION FAN 2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2024-09-27 16:06:19', '2024-09-27 16:07:25', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2024-09-27 16:06:19', '2024-09-27 16:07:25', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
