  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot HOV-84505 activate fail alarm at HMI', 'Electrical & Instrument', 'CM ', 'Completed', '2024-09-30', '<p><span style="background-color: rgb(255, 255, 0);">Troubleshooting HOV-84505 activate fail alarm at Flow Control Valve Train B.</span></p><p>1.Found HOV valve open status signal is latch at Rotatory Limit Switch and so HOV valve get open signal always even though HOV valve is totally close.</p><p>2.Cleaning the wiring terminal of signal cable and so used spare Rotatory Limit Switch for Open Status.</p><p>3.Perform function test of HOV Valve Open/Close position and status at CCR HMI and also monitor the function of Rotatory Limit Switch. Now, unit is back in service.</p>', NULL, '2024-09-30 17:30:41', '2024-09-30 17:32:23', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-HOV-84505', 'ATL-MS-HOV-84505', 'HOV, 16"-PG-84008-FS1N to FCV-84502B', NULL, NULL, 'HOV, 16"-PG-84008-FS1N to FCV-84502B', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ivan', NULL, 'EXTERNAL', '2024-09-30 17:30:41', '2024-09-30 17:32:23', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech');
