  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'New battery bank 1 replacement  for G8930', 'Electrical & Instrument', 'CM', 'Completed', '2024-10-02', '<p><b><u>Today Activity&nbsp; (Day2)</u></b></p><p>Replace new batteries at G8930 battery bank 1.</p><p><b><u><br></u></b></p><p><b><u>Action&nbsp;</u></b></p><p>Prepared work permit (ZOC-HWP-2024---01082).</p><p>Isolated FM-200 system.</p><p>Disconnected and removed old batteries.</p><p>Re-connected back the new batteries.</p><p>de-isolated FM-200.</p><p>Tested run G8930 for 1 hour to charge the new battery.</p><p>No abnormality are found.</p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">History : Day (1)</u></b></p><p><u style="background-color: rgb(255, 255, 0);">Today Activity&nbsp;</u></p><p><span style="background-color: rgb(255, 255, 0);">Replace bolt and nut of the Alternator G8930.<br><u>History</u><br>The temporarily installed bolts of the alternator are not long enough.<br><u>Action</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Replace 5 sets of bolts and nuts.<br>Spanner size:19mm&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Torque 80 Nm.<br><br>Note : The extra bolts and nuts are store at the generator drawer of E&amp;I cold store.</span></p>', NULL, '2024-10-02 16:27:49', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
