-- Inserting report ID 19525
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot fuel dispenser auto running error', 'Electrical & Instrument', 'CM', 'Completed', '2024-10-03', '<p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 255);" data-darkreader-inline-bgcolor=""><b style="text-decoration-line: underline;">Today Activity</b><br>Trouble shoot fuel dispenser auto running error.<br>Problem issue: The dispenser error occur again.<br><b style="text-decoration-line: underline;">Action</b><br>Replaced 3 new capacitor 3kV for board 1.<br>Replaced 3 new capacitor 3kv for board 2.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 255);" data-darkreader-inline-bgcolor=""><u><b><br></b></u></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 255);" data-darkreader-inline-bgcolor="">Function test and<br>the diesel dispenser unit 1 is working properly back to normal.</span></p><p><span style="--darkreader-inline-bgcolor: #000000;" data-darkreader-inline-bgcolor=""><br><span style="background-color: rgb(255, 255, 255);">For unit 2 is still malfunction.<br></span>Inspect that the relay from board 2 is damaged.<br><span style="background-color: rgb(255, 255, 255);">Plan to replace new driver board when it is arrived.</span><br><br><br><b style="text-decoration-line: underline; background-color: rgb(255, 255, 0);">History (29-Aug-2024)</b></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Troubleshoot fuel dispenser auto running error</span></p><p><u style="--darkreader-inline-bgcolor: #000000;" data-darkreader-inline-bgcolor=""><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">During operate the diesel dispenser, check and monitor with operator.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">No abnormal found and still monitoring.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Waiting for new spare part arrive.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><u><br></u></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><u>History (28-08-2024)</u><br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Troubleshoot fuel dispenser auto running error</span></p><p><u style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Action</u></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">The dispenser didn''t stop after diesel filling. Operator inform to us.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Found the last one driver board was faulty.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Isolated the unit and checked electrical wiring.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Measured coil resistance and Insulation resistance test solenoid both units.(OK)</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Checked the limit switch. (OK)</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Measured motor resistance and Insulation resistance test. (OK).</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Remove driver board and magnetic contactor for test at workshop.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Found one capacitor damaged at driver board.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Replace with the new capacitor.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">After replacing, checked and function test driver board at workshop. (OK)</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Checked and function test magnetic contactor, there is a buzzing sound.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Replaced the new magnetic contactor.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">After this replacement, the diesel dispenser worked properly with one unit,<br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">and the auto running error was resolved.<br>Plan to install the new board for damage one, once the spare part arrives.</span></p><p><span style="background-color: rgb(255, 255, 0);"><span style="--darkreader-inline-bgcolor: #0000cc;" data-darkreader-inline-bgcolor="">Performer : NL, Bone, Jack</span><br></span></p><p><u style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><br></u></p><p><u style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">History (27-08-2024)</u></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Troubleshoot fuel dispenser auto running error</span></p><p><u style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Action</u></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">The dispenser has two units for filling diesel and two driver boards.<br>One board was functioning properly.<br>Isolated the damaged board and installed the working board in its place.<br>After this adjustment, the diesel dispenser worked properly with one unit,<br>and the auto running error was resolved.<br>Plan to install the new board for damage one, once the spare part arrives.</span></p><p><span style="background-color: rgb(255, 255, 0);"><span style="--darkreader-inline-bgcolor: #0000cc;" data-darkreader-inline-bgcolor="">Performer Bone/Nay/Jack</span><br><br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><u>History(07-Aug-2024)</u><br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">Troubleshoot fuel dispenser auto running error.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><u>Action</u><br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Checked&nbsp;<u>3100-DRV3003V70 motor driver board</u>&nbsp;condition.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Found driver board was burned by dead lizard.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Found one of socket cable was broken. (Repaired)</span></p><p><span style="background-color: rgb(255, 255, 0);"><span style="--darkreader-inline-bgcolor: #000000;" data-darkreader-inline-bgcolor="">- Need to replace new driver board for auto running error.</span><br><span style="--darkreader-inline-bgcolor: #0000cc;" data-darkreader-inline-bgcolor="">Performer Francis/Htet Aung/HMM</span></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><u>History(03-Aug-2024)<br></u>Troubleshoot fuel dispenser auto running error.<br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor=""><u>Action</u><br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Found some water seeping in the keypad display box.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Cleaned and checked circuit board of keypad display. (Normal condition)<br></span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Checked and tested limit switch of nozzle. (Working properly)</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Visual checked I/O card and power board condition in control panel.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Bypassed signal of run motor.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Motor was still running after de-isolation.</span></p><p><span style="--darkreader-inline-bgcolor: #000000; background-color: rgb(255, 255, 0);" data-darkreader-inline-bgcolor="">- Need to check power board.</span></p><p><span style="background-color: rgb(255, 255, 0);"><span style="--darkreader-inline-bgcolor: #000000;" data-darkreader-inline-bgcolor="">- In progress</span><br><span style="--darkreader-inline-bgcolor: #0000cc;" data-darkreader-inline-bgcolor="">Performer&nbsp;Francis/Htet Aung/HMM</span></span></p><p><br></p>', NULL, '2024-10-03 15:57:04', '2024-12-31 10:41:57', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8905', 'ATL-OC-A-8905', 'ZOC Diesel Dispenser unit', NULL, NULL, 'ZOC Diesel Dispenser unit', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2024-10-03 15:57:04', '2024-12-31 10:41:57', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2024-10-03 15:57:04', '2024-12-31 10:41:57', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec');
END $$;

