  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Complax; Vibration monthly measurement of Sep 2024', 'Mechanic', 'PM', 'In Progress', '2024-10-02', '<p>Vibration monthly measurement of Sep 2024</p><p>-&nbsp; &nbsp; Fire water pump P-8210,8220,8230.</p><p>-&nbsp; &nbsp; Turbo generator TG-8610.</p><p>-&nbsp; &nbsp; Turbo compressor train 1,2,3.</p>', NULL, '2024-10-03 17:43:09', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL, false, 'G2N') RETURNING id INTO new_report_id;
