-- Inserting report ID 19640
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'P8805B water dam pump trip and fail alarm.', 'Electrical & Instrument', 'CM', 'Waiting for Material', '2024-10-07', '<p><b><u>Today’s Activity<br></u></b>Check the inside of the junction box of the P-8805B for any signs of water ingress.&nbsp;<br><b><u>Found<br></u></b>Small Moisture found in the junction box.<br><b style="text-decoration-line: underline;">Action:&nbsp;</b><br>Clean the moisture of the junction box.<br><span style="background-color: rgb(0, 255, 0);">Waiting the spare part.</span><br><br><br><b><u style="background-color: rgb(255, 255, 0);">History (29/Sep/2024)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">P8805B water dam pump trip and fail alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Measured the insulation resistance of the P8805B at the control junction box:</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- U1 to E: 0.00 MOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- V1 to E: 0.00 MOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- W1 to E: 0.00 MOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">Inspected the terminal junction box above the pump structure and found it filled with water.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Cleaned the junction box and wire terminals.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">After cleaning, remeasured the insulation resistance:<br></span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- U1 to E: 0.03 MOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- V1 to E: 0.03 MOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- W1 to E: 0.03 MOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">Conducted a test run of the P8805B, monitoring for 15 minutes with no abnormalities.</span></p><p><span style="background-color: rgb(255, 255, 0);">P8805B is working properly.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><strong>Recommendation:</strong> The junction box is aging and should be replaced.<br></span></p><p><br></p>', NULL, '2024-10-07 10:14:14', '2024-10-07 14:55:28', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
