-- Inserting report ID 19773
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot error of G8020 at ZBV-1', 'Electrical & Instrument', 'CM', 'Completed', '2024-10-10', '<h3 class="modal-title displayform"><p><u><b>Today Activity</b></u></p><p>Troubleshoot error of G8020 at ZBV-1</p><p><br></p><p><u><b>Alarm</b></u></p><p>Found alarms -&nbsp; Wrn LO Fuel level</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; Stp GCB fail</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp; Fls Oil Presssure&nbsp;</p><p><b><u>Action</u>&nbsp;</b></p><p>Firstly alarm reset, there is no alarms at control panel.<br>Open Junction boxes for cleaning and retighten wiring termination.<br>Check the terminal of the AVR box.</p><p>Check the battery voltage and&nbsp; charging voltage.</p><p>Check Battery water level<br>Cleaned terminal .<br></p><p>Test run the G8020 from Local control panel. Test run Ok.</p><p>After that Test run from control room.&nbsp;</p><p>Now Unit back to normal and online.</p></h3>', NULL, '2024-10-10 14:59:00', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8020', 'ATL-BV1-G-8020', 'Gen, ZBV1 Diesel generator No2', NULL, NULL, 'Gen, ZBV1 Diesel generator No2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8020-PACKAGE', 'ATL-BV1-G-8020-PACKAGE', 'Gen, ZBV1 Diesel Generator package2', NULL, NULL, 'Gen, ZBV1 Diesel Generator package2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2024-10-10 14:59:00', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL);
