  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-CARLIFT', 'ATL-OC-CARLIFT', 'ZOC Carlift', NULL, NULL, 'ZOC Carlift', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
