  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Inspect Diesel Gen at YADANA', 'Electrical & Instrument', 'OTH', 'Completed', '2024-10-13', '<p><u><b>Today''s Activity</b></u><br></p><p>Inspect Diesel Gen&nbsp;&nbsp;( 50 KVA )&nbsp;at YADANA</p><p><br></p><p><u><b>Action</b></u></p><p>Firstly Communicate with YADANA teams<br></p><p>Check Engine oil level ( OK )</p><p>Check Diesel level ( OK )&nbsp;</p><p>Check coolant water level&nbsp; ( OK )</p><p>Check battery water level ( OK )</p><p>Check battery voltage ( 25.28 DCV )</p><p>Generator running hours&nbsp; ( 4142.6 Hrs. )</p><p>Generator test run with load</p><p>Check ammeter selector switch ( malfunction )</p><p>Check voltage adjust switch is working but a little bit difficult to adjust.</p><p>Check leakage relay ( OK )</p><p>Check generator output voltage&nbsp;</p><p><b><u>3 Phase&nbsp;</u></b></p><p>L1L2&nbsp; -&nbsp; 403.7 V</p><p>L2L3&nbsp; -&nbsp; 404.5 V</p><p>L1L3&nbsp; -&nbsp; 403.1 V</p><p><b><u>Single Phase&nbsp;</u></b></p><p>L1N&nbsp; -&nbsp; 231.7 V</p><p>L2N&nbsp; -&nbsp; 232.6 V</p><p>L3N&nbsp; -&nbsp; 234.1 V</p><p>Check generator frequency - 52.9 Hz</p><p>Test emergency stop when generator running&nbsp; ( switch is OK )</p><p><br></p><p><u><b>Start Procedure</b></u>&nbsp;</p><p>-Start glow</p><p>-Turn to start&nbsp;</p><p>-Run with idle ( 5min )</p><p>-Push to Run</p><p>-Main Breaker On</p><p><b><u><br></u></b></p><p><b><u>Test Equipment</u></b></p><p>Fluke 124&nbsp; Industrial Scope meter&nbsp; 40MHz</p><p>Fluke 87 V True RMS&nbsp; multimeter&nbsp;<br><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br><br></p>', NULL, '2024-10-13 14:18:23', '2024-10-13 14:27:32', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
