-- Inserting report ID 19981
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Kobelco Hydraulic Seeping at KP-30', 'Mechanic', 'CM', 'Completed', '2024-10-15', '<p><u><b>Activity</b></u></p><p>Troubleshoot Hydraulic Seeping Kobelco Mini Excavator at KP-30.</p><p><br></p><p><u><b>Action</b></u></p><p>- Checked the suspected hydraulic lines visually.</p><p>- Checked the hydraulic level.</p><p>- Topped up Hydraulic (PTT Hydraulic 68 - 5 Liters).</p><p>- Start the excavator and function test.</p><p>- Checked the hydraulic lines.</p><p>- Removed the swivel joint guard.</p><p>- <span style="background-color: rgb(255, 255, 0);">Found seeping at the outlet of swivel joint on the forward line of the left travel motor.</span></p><p>- Removed the left side travel motor guard.<br></p><p>- <span style="background-color: rgb(255, 255, 0);">Found the forward return line of the left travel motor is defective.</span></p><p>- Removed two defective hydraulic hoses.</p><p>- Installed the caps on the respective fittings.</p><p>- Housekeeping.</p><p><br></p><p><u><b>On 16-Oct-2024</b></u></p><p>- Fabricated the hydraulic hose at Dawei.</p><p>- Removed the caps on the respective fittings.</p><p>- Cleaned the fittings.</p><p>- Replaced the defective hoses(2EA) for the left side travel motor.</p><p>- Checked and tightened the fitting&nbsp;</p><p>- Function test and checked Hydraulic Leak.</p><p>- Checked Hydraulic level.</p><p>- Applied Denso Tape on the fitting.</p><p>- Installed the guard and cover.</p><p>- Housekeeping</p><p><br></p><p><u><b>Required Tools</b></u></p><p>- Cable Tie</p><p>- Knife</p><p>- Adjustable Wrench</p><p>- Pipe Wrench</p><p>- Funnel</p><p>- Socket Set</p><p>- Spanner Set</p><p>- Allen Key Set</p><p>- Zip Lock</p><p>- Red Bag</p><p><br></p>', '<p>There is only one hydraulic hose(Reverse Line) left to replace for the left side travel motor.</p><p><br></p>', '2024-10-15 22:11:30', '2024-10-19 14:10:31', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-EXCAVATOR-01', 'ATL-OC-EXCAVATOR-01', 'Mini Excavator-KOBELCO', NULL, NULL, 'Mini Excavator-KOBELCO', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
