-- Inserting report ID 20066
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Calibration to ensure that the transmitter 2LIT-58', 'Instrument', 'CM', 'Completed', '2024-10-18', '<div>Calibration to ensure that the transmitter is properly calibrated and accurate readings for 2LIT-58200A</div><div>As found value:&nbsp; LRV -563 mmH20,&nbsp; &nbsp;URV 1,345 mmH2o</div><div>The density of the fluid&nbsp; = 0.83</div><div>As found head pressure = - 743 mmH2O&nbsp;</div><div><br></div><div>Head pressure by calculation ; -800 x 0.934 = - 747 mmH2O</div><div>LRV by calculation&nbsp;; (0.83 x 218) - 747 = - 566 mmH2O</div><div>URVby calculation ; [0.83 x (2300+218)] - 747 = 1,343 mmH2O</div><div><br></div><div>Calibration checks by applying pressure. The result is below&nbsp;</div><div><br></div><div>%&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;mmH2O&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;mA</div><div><br></div><div>0&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 179&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3.95</div><div>25&nbsp; &nbsp; &nbsp; &nbsp; 656&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 7.97</div><div>50&nbsp; &nbsp; &nbsp; &nbsp; 1133&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 11.98</div><div>75&nbsp; &nbsp; &nbsp; &nbsp; 1610&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 15.99</div><div>100&nbsp; &nbsp; &nbsp; 2087&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 19.98</div><div>------------------------------------------</div><div><br></div><div>- Online the transmitter back to service found the reading is 83.5 %</div><div>- Temporarily install glass level using a clear vinyl tube to measure the height. The reading about 83-85%<br></div><div><br></div>', NULL, '2024-10-18 17:02:36', '2024-10-19 08:15:53', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2LIT-58200A', 'GBS-2LIT-58200A', 'LEVEL INDICATOR TRANSMITTER', NULL, NULL, 'LEVEL INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2024-10-18 17:02:36', '2024-10-19 08:15:53', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Lue', NULL, 'EXTERNAL', '2024-10-18 17:02:36', '2024-10-19 08:15:53', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT');
END $$;

