  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'EDG-8620 Perform mechanical 6MPM', 'Mechanic', 'PM', 'Complete', '2024-10-18', '<p><b><u>Diesel engine.</u></b></p>  <p>&nbsp;</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; General inspection of engine for debris.</p><p>.&nbsp; &nbsp; &nbsp; &nbsp;Cleaned engine crank case breather&nbsp;</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Checked the condition of gauges, they are normal condition.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Checked engine crankcase oil level, dipstick it’s full.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Checked belt tension are normal condition.</p><p>.&nbsp; &nbsp; &nbsp; &nbsp;Running 812.05 Hrs.</p>  <p><br></p>  <p><b><u>Cooling system.</u></b></p>  <p>&nbsp;</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Checked engine coolant level, it’s full.&nbsp; &nbsp;</p>  <p>·&nbsp; &nbsp; &nbsp; &nbsp;Apply grease all greasing points.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Visual inspected coolant line connection and hoses are normal condition.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Checked water cooling pH = 9</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Visual inspected coolant pump no found leak.</p>  <p><br></p>  <p><b><u>Fuel system.</u></b></p>  <p>&nbsp;</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Checked for any leaking were normal condition.</p>  <p>·&nbsp; &nbsp; &nbsp; &nbsp;Drained sediment and water from fuel Separator.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Cleaned and check the fuel primary filter. It’s normal condition</p>  <p>&nbsp;</p>  <p><b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <u>Air induction system</u></b></p>  <p>&nbsp;</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Inspected air inlet system, it''s normal.</p>  <p>·&nbsp; &nbsp; &nbsp; &nbsp;Cleaned air filter blow by by air.</p>  <p>&nbsp;</p>  <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b><u>Hydraulic starting system</u></b></p><p>.&nbsp; &nbsp; &nbsp;Checked&nbsp; oil level, it’s full.</p><p>.&nbsp; &nbsp; &nbsp;Visual inspected HYD line connection and hoses were normal condition.</p><p>&nbsp;</p>', 'HYD star mode was failures.&nbsp;', '2024-10-19 06:30:06', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL, false, 'G2N') RETURNING id INTO new_report_id;
