-- Inserting report ID 20306
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'G-9115 T/S cannot start up', 'Mechanic', 'CM ', 'In Progress', '2024-10-24', '<p>Job Steps :</p><p><br></p><p>&nbsp; 1. Swapping timing disc from G-9110 to G-9115 and original magnetic timing pickup sensor from G-9115</p><p>&nbsp; 2. ZPR resetting to default setting. (2mm gap)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;ZPR&nbsp; A 18 turns.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;ZPR B 14 turns.&nbsp;</p><p>&nbsp; 3. Check the continuity of Ignition coils and DISN unit outputs and inputs.</p><p>&nbsp; 4. If outputs and inputs are valid, will perform test run.</p><p>&nbsp;5. Test run for 30 mins.</p><p>6. Stop for 10 mins and start up again to make sure the correct value of ZPR.</p><p>7. Stop the generator after 2nd time start up.</p><p>8. Adjust the ZPR value of A 18 turns to 17 turns.</p><p>9. Test run the engine.</p><p>        </p><p><br></p>', NULL, '2024-10-24 17:29:37', '2024-10-24 17:40:55', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patrick', NULL, 'EXTERNAL', '2024-10-24 17:29:37', '2024-10-24 17:40:55', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech');
END $$;

