-- Inserting report ID 20316
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Commissioning of Solar power system at ZBV1. ', 'Electrical & Instrument', 'OTH', 'Completed', '2024-10-24', '<p><u><b>Today’s Activity</b><br></u>Commissioning of Solar power system at ZBV1.&nbsp;<br><b><u>Action&nbsp;</u></b></p><p>-Check and measure voltage and current at Bus bar connection panel BCP-8001</p><p><br></p><p>-Check and functional test 24VDC&nbsp; Lighting inverter control panel</p><p>&nbsp; (1) Check pilot lamp indicator, functional test (OK)</p><p>&nbsp; (2) Check circuit breaker for operation test and continuity test&nbsp; (OK)</p><p>&nbsp; (3) Check inverter input and output (OK)</p><p>&nbsp; (4) check and test run thermostat and panel indoor cooling fan (OK)</p><p><br></p><p>-Check and functional test Ventilation Control Panel (VCP-8001)</p><p>&nbsp; &nbsp;(1) Check pilot lamp indicator, functional test (OK)</p><p>&nbsp; &nbsp;(2) Check circuit breaker for operation test and continuity test&nbsp; (OK)</p><p>&nbsp; &nbsp;(3) Check and test emergency stopped bottom (OK)</p><p>&nbsp; &nbsp;(4) Check and test relay, contactor, overload and breaker (OK)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ( Set the overload setting - 2.1 A )</p><p>&nbsp; &nbsp;(5) Check 600W power inverter input and output (OK)</p><p>&nbsp; &nbsp;(6) Check and test run Panel indoor cooling fan.</p><p><br></p><p>-Firstly power source from Generator , after that switch on from solar power source.</p><p>&nbsp;All load side are working properly.</p><p>-When Generator and breaker off, at that time power source from solar power. After 2 hrs, we got the alarm from VHF and CCTV panel because of low battery volts.</p><p>-Inform to CCR</p><p><br></p><p><u><b>Need to take action</b></u></p><p>-Need to put the striker for all circuit breaker update status.&nbsp;</p><p><br></p><p><br></p><p><br></p><p><br><br></p>', NULL, '2024-10-24 18:37:16', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-DCUPS-8001', 'ATL-BV1-DCUPS-8001', 'ZBV1 DCUPS System 8001', NULL, NULL, 'ZBV1 DCUPS System 8001', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
