-- Inserting report ID 20341
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot breaker fault at smoking area.(GMT)', 'Electrical & Instrument', 'CM', 'Completed', '2024-10-25', '<p><u>Today’s Activity<br></u>Troubleshoot breaker fault at smoking area. (with GMT team)</p><p><br><u>Action&nbsp;</u></p><p>-Checked main breaker supply voltage and breaker tripped condition.</p><p>-Found power socket breaker and lighting breaker are tripped.</p><p>-Checked and continuity test.</p><p>-Found&nbsp; 149.3 Ohm within Line cable and ground.</p><p>-Checked wiring condition.</p><p><br></p><p>- 1) Found one cable was cracked. (covering with electrical tape)</p><p>- 2) Found 2 Gang switch beside snooker was bad performance and breaker tripped. (Replace new switch)</p><p>- 3) Found one light was damaged. (no stack for spare part)</p><p>- 4) Found switch socket outlets were fault. (cleaning and sealing with electrical tape)</p><p>- 5) Reinstall voltmeter of main circuit breaker.</p><p><br></p><p>- After fixing all cases, breaker was not tripped again.</p><p>- Now, monitoring condition.</p><p><br></p><p><br></p>', NULL, '2024-10-25 17:12:47', '2024-10-25 17:52:12', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
