  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S G-9110 cannot start up Day 3', 'Mechanic', 'CM ', 'In Progress', '2024-10-26', '<p>T/S G-9110 cannot start up Day 3</p><p><br></p><p>Job Steps :</p><p><br></p><p>1. Adjust the actuator linkage length from 40cm to 41 cm.</p><p>2. Check breather cases and filters, lube oil level, water content and Test run without load for 5 mins. Found there was a leak at Bank B turbocharger exhaust side.</p><p>3. Stop the generator and monitor. Participate in Way Ward meeting. Cleaned the leak area.</p><p>4. Test run without load for 5 mins, shared load for 10 mins. (found no leak)</p><p>5. Closely monitor the condition and parameter for 1 hour.&nbsp; Found no abnormal.</p><p>5. Test run to 6:00PM and stop the generator.</p><p>7. Will continue test run tomorrow with same parameter.</p>', NULL, '2024-10-26 16:39:11', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patrick', NULL, 'EXTERNAL', '2024-10-26 16:39:11', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL);
END $$;

