  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S mobile generator G-02 malfunction.', 'Electrical', 'CM', 'Completed', '2024-10-26', '<div>&nbsp;T/S mobile generator G-02 (YDG-xx77) malfunction at AQP/LD</div><div>&nbsp;- Found Phase U and V Winding Temperature, Bearing DE and NDE Temperature alarm on Operation Display Panel.</div><div>- Verified Temp Element that found normal resistance around 111 Ohm @&nbsp;<b><i>Ambient Temp&nbsp;</i></b>for all and wiring cable are in good condition.</div><div>- Found Analog Input module (IS-AIN8) poor condition by terminal connection and IC on PCB corroded cause to AI alarm and unable to start.</div><div>- Connect Laptop to Controller (IG-NTC-BB) via USB cable with application InteliMonitor (ComAp PC Suite) for verified values and configure.</div><div>- Tried to disable protection of AI1(U-Winding) and AI2(V-Winding) due to no spare part for replace.</div><div>- Reset the alarm was cleared, but found NDE and DE Bearing fault in sometime.</div><div>- Disable protection of AI3(W-Winding), AI4(NDE-Bearing Temp) and AI5(DE-Bearing Temp) for override fault then download configure to controller.&nbsp;</div><div>- Reset alarm then selected mode from OFF to MAN and start the engine.</div><div>- Tried to stop and start engine again.</div><div>- Monitor Measurements value, Gen Volt L-N = 233 VAC / 50 HZ @ 1498 rpm</div><div>Completed.</div><div><br></div><div>&nbsp;</div>', '<p>Photo:</p><p>\\\\pttep.com\\DFSRootART\\ARTShare\\Selective Access\\02-PAT-M\\02-PAT-M_El\\04 - Electrical_Instrument\\18-EI Pictures Database\\Mobile Gen Picture\\ART-G-02_APP-UD\\G-02_YDG-xx77\\20241026_WindingTempFail</p>', '2024-10-26 17:16:59', '2024-12-03 10:06:04', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
