  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Winyoo N.', NULL, 'EXTERNAL', '2024-10-26 17:16:59', '2024-12-03 10:06:04', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
