-- Inserting report ID 20455
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 3MPM H2S Analyzer 2AIT-39909', 'Instrument', 'PM', 'Completed', '2024-10-28', '<p>Perform 3MPM H2S Analyzer 2AIT-39909 follow procedure.&nbsp;</p><p><font color="#9c9c94">- Before PM Analyzer reading 22.2 ppm/v. and use table 30 ppm/v</font></p><p><font color="#9c9c94">1. Put H2s value to keypad mode on last value at 22.2 ppm/v</font></p><p><font color="#9c9c94">2.As found zero reading&nbsp; = 0.0113ppm/v</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; point 30 ppm&nbsp; &nbsp;= 22.92 ppm/v</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; point 60 ppm&nbsp; &nbsp;= 38.567&nbsp; ppm/v&nbsp;</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; point 100 ppm = 67.35&nbsp; ppm/v&nbsp;&nbsp;</font></p><p><font color="#9c9c94">3.Perform local maintenance&nbsp;</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced membrane filter = 1 ea. (&nbsp; P/N:850-09E ),60.52.17.101.3</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced coalescer filter = 1 ea. (&nbsp; P/N:073.028-00 ),60.51.74.105.3</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Replaced humidifier filter in the solution tank = 1 ea.(&nbsp; P/N:070.300-00 ),60.51.74.133.3</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Clean tank and fill up the humidity solution&nbsp; (&nbsp; P/N:055.335-00 ),60.51.74.134.3</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Clean detector and sensing tape roller guide</font></p><p><font color="#9c9c94">4.Calibration point 30,60,100 ppm/v has been passed&nbsp;</font></p><p><font color="#9c9c94">5.As left zero reading&nbsp; = 0.1324 ppm/v</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;point 30 ppm&nbsp; &nbsp;= 29.863ppm/v</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;point 60 ppm&nbsp; &nbsp;= 60.27&nbsp; ppm/v&nbsp;</font></p><p><font color="#9c9c94">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;point 100 ppm = 100.6 ppm/v&nbsp;&nbsp;</font></p><p><font color="#9c9c94">6.Online process analyzer reading&nbsp; 23.431 ppm/v</font></p><p></p><p><font color="#9c9c94">&nbsp; &nbsp; *keep monitor and wait for Lab test result on tomorrow .*</font></p><p>- Compare analyze data between lab and analyzer</p><p>&nbsp;Found lap sample result is 24 PPMV while analyzer reading 25.537 PPMV. (Result was pass)</p><p>- Put unit to measured mode and inform PTT rep.</p>', NULL, '2024-10-28 16:52:21', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2AIT-39909', 'GBS-2AIT-39909', 'H2S ANALYZER INDICATOR TRANSMITTER', NULL, NULL, 'H2S ANALYZER INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Theeraphan', NULL, 'EXTERNAL', '2024-10-28 16:52:21', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sompong', NULL, 'EXTERNAL', '2024-10-28 16:52:21', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL);
END $$;

