  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2LIT-32102 & 32103 different reading.', 'Instrument', 'CM', 'In Progress', '2024-10-28', '<p>T/S 2LIT-32102 &amp; 32103 different reading in below details.</p><p>-As found checked on site&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - 2LIT-32102 reading 34.2%</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - 2LIT-32103&nbsp;reading 80.3%</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; -Level indicator reading 35.5%</p><p>&nbsp;-Performed flushing impulse lines of 2LIT-32103 found there was no sludge coming out.</p><p>&nbsp; &nbsp; -Rechecked both&nbsp; transmtters configuration.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - S.G @ 0.86</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - URV@ -158 mmH20</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - LRV@&nbsp; -1190 mmH20</p><p>-Peformed impulse line self isolation and drain found&nbsp; the reading value was -40.5% @ -500 inH20</p><p><br></p><p>-Recalibrated 2LIT-32103 by applying 912 mmH20 to transmitter but the transmitter could not be corrected due to " exceed correction value"</p><p><br></p><p>-Now the error was shifted from 40% to 80%.</p><p>-Transmitter need to be replaced.</p><p><br></p>', NULL, '2024-10-28 17:42:49', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2LIT-32102', 'GBS-2LIT-32102', 'LEVEL INDICATOR TRANSMITTER', NULL, NULL, 'LEVEL INDICATOR TRANSMITTER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
