  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sompong J.', NULL, 'EXTERNAL', '2024-10-28 17:42:49', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL);
