  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, ' Check and verify line break function of HOV-83000', 'Electrical & Instrument', 'OTH', 'Completed', '2024-11-01', '<p><u>Today Activity</u></p><p>Check and verify line break function of HOV-80000 at ZBV-1</p><p><br></p><p><u>Action</u></p><p>- Checked control panel of HOV83000 line break system.</p><p>- Function test for HOV while bypass valve was opening after commissioning PMOE solar installation.</p><p>- Changed local mode to remote.</p><p>- Opened HOV by remote from CCR.</p><p>- Record the event log.</p><p>- Checked minor and major activation with time duration 1 min.</p><p>- Found minor activation was no time duration. (ROD was over 13 psi/m)</p><p>- Major activation was not clear after ROD over 14psi/m in a few sec.</p><p>- Major activated alarm cannot be cleared.</p><p>- HOV was closed by ROD major alarm.</p><p>- HOV had no action even ROD minor activation alarm.</p><p>- After function test, reset alarm.</p><p>- Opened HOV by remote from CCR.</p><p>- Operated process back to normal condition in local mode.</p><p><br></p>', NULL, '2024-11-01 17:51:53', '2024-11-05 20:09:34', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
