-- Inserting report ID 20629
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'BKT-G-08 Troubleshoot engine start failures / YPM.', 'Mechanic', 'CM', 'In Progress', '2024-11-01', '<p>BKT-G-08 Troubleshoot engine start failures and perform YPM.</p><p>- Start the engine and found “Start/Emergency Lever” cannot hold on start position.</p><p>- Removed air shut off valve for check.</p><p>- Found sling of air shut off valve damaged and replaced new sling.</p><p>- Reinstalled air shut off valve and function test was normal condition.</p><p>- Replaced lube oil filter, fuel filter and air filters.</p><p>- Replaced new lube oil around 3 liters.</p><p>- Inspected coolant water PH 7.</p><p>- Cleaned flame arrestor.</p><p>- Before install original flame arrestor, used dummy flame arrestor for test run around 15 mins.</p><p>- Installed backed original flame arrestor.</p><p>- Inspected general condition of engine.</p><p>- When testing run coolant was leaking from cap and repaired at workshop and installed back.</p><p>- Test run again and found radiator leak&nbsp; but can not fix. (Need to replace new part)</p><p><br></p><p><br></p><p></p>', 'Z:\\0312 TBF\\Department Share\\Archive folders\\02-PBN-M\\03 MM\\06. Pictures\\04 Mobile Equipment\\Generator\\BKT-G-08\\20241102 Perform YPM', '2024-11-02 09:31:03', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-BKT-G-08', 'GBN-BKT-G-08', 'MOBILE GENERATOR 8', NULL, NULL, 'MOBILE GENERATOR 8', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
