  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Win', NULL, 'EXTERNAL', '2024-11-02 09:31:03', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Apiratchasit', NULL, 'EXTERNAL', '2024-11-02 09:31:03', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL);
