  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tawatchai P', NULL, 'EXTERNAL', '2024-11-03 22:05:55', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL);
