  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-W4890/4900/4910.PK', 'ART-W4890/4900/4910.PK', 'APP WASTE HEAT POWER GEN TURBINE PACKAGE', NULL, NULL, 'APP WASTE HEAT POWER GEN TURBINE PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
