  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TC1 T/S VSH-322781 vibration high', 'Instrument', 'CM', 'Under Monitoring', '2024-11-04', '<div class="ewa-rteLine">T/S VSH-322781 vibration high so to the 2KM-322781 cooler fan motor stop.</div><div class="ewa-rteLine">- Verified limit switch VSH-322781 at local side, found it good condition normal working.</div><div class="ewa-rteLine">&nbsp; &nbsp;* Limit switch use normally close (NC) and measure voltage = 0 Vdc.</div><div class="ewa-rteLine">&nbsp; &nbsp;* Verified by simulate test, if the actually activate shall be reset by manual. But in this case activate alarm high and auto clear.&nbsp;</div><div class="ewa-rteLine">- Verified loop wiring and retighten terminal.</div><div class="ewa-rteLine">- Analyze, may be activate by surge protection, therefore replace surge protection (SD32X) by new spare.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">&nbsp;</div>', NULL, '2024-11-04 14:52:38', '2024-11-04 15:05:48', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\GBS.Turbine-Tech', false, 'G2S') RETURNING id INTO new_report_id;
