-- Inserting report ID 20740
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '12MPM on G-9125 Day 1', 'Mechanic', 'PM ', 'In Progress', '2024-11-04', '<p>Job Description : 12MPM on G-9125 Day 1</p><p><br></p><p>Job Steps :</p><p><br></p><p>1. Precheck and isolations.</p><p>2. Cleaned radiator, fan apartment and compartment with compressed air.</p><p>3. Checked fan belt condition and tension.</p><p>4. Checked fan bolts and nuts. Checked and inspected with bore scope.</p><p>5. Visually inspected water pump, hoses, lube oil system leak, breather filters and other parts.</p><p>6. Checked and tightened the bolts and nuts.</p><p>7. Cleaned air filters with compressed air. check the turbocharger and line with bore scope.</p><p>8. Replaced new fuel diesel filter. drained water.</p><p>9. Test the fuel pump.&nbsp;</p><p>10. Replace alternator belt and checked tension.</p><p>11. Housekeeping and deisolate for emergency.</p>', NULL, '2024-11-04 16:21:19', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9125-PACKAGE', 'ATL-MS-G-9125-PACKAGE', 'Gen, ZMS Diesel Generator Package', NULL, NULL, 'Gen, ZMS Diesel Generator Package', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patrick', NULL, 'EXTERNAL', '2024-11-04 16:21:19', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Junior', NULL, 'EXTERNAL', '2024-11-04 16:21:19', CURRENT_TIMESTAMP, 'PTTEP\\ZMS.MTN-Tech', NULL);
