  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG-5630, Performed engine crank soak wash and firi', 'Mechanic', 'PM', 'Complete', '2024-11-04', '<p>TG-5630, Performed engine crank soak wash and firing the unit.</p><p>- Prepared PTW, tools , equipments and crank soak wash machine.</p><ul type="disc"><li>- Connected air line for Supply&nbsp;<u>40</u>&nbsp;Psi sealing dry air to reduction gearbox and engine bearing.</li><li>- Prepared Distillate water&nbsp;15 Gallons &amp; chemical cleaning ZOK 1 gallon total solution 16 gallons.</li><li>- Performed crank soak wash as follow&nbsp;<i><u>new procedure</u></i>&nbsp;crank soak wash.</li><li>- Perfromed cranking and injected chemical for cleaning 2 times .</li><li>- Each time of chemical, waiting 15-30 minutes for soaking. (Total 100 liters).</li><li>- Perfromed cranking and injected Distillate water for cleaning for 4 times (Total 200 liters).</li><li>- Cranking the engine for dry crank 2 times. ( 5 Minutes / Time)&nbsp;</li><li>- Starting the engine with gas mode for firing about 10 minutes and&nbsp;R/H. 34,370 hrs.&nbsp;</li><li>- Inspected and check any leak in the enclosure.</li><li>- Cleaned inside and outside skid.</li><li><br></li></ul><p></p>', NULL, '2024-11-04 19:26:12', '2024-11-04 20:25:58', 'PTTEP\\Bongkot.turbine-Mech', 'PTTEP\\Bongkot.turbine-Mech', false, 'G2N') RETURNING id INTO new_report_id;
