-- Inserting report ID 20771
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG-5630, Perform mechanical 8 KPM', 'Mechanic', 'PM', 'Complete', '2024-11-04', '<p>TG-5630, Perform mechanical 8 KPM. (Completed)</p><p>On 4 Nov 2024.</p><p>- Performed engine crank soak wash and firing the unit.</p><p>- Performed process and mechanical isolation.</p><p>- Perfomed spading of liquid (2’ #150) and fuel gas system (2” #300).</p><p></p><p>On 5 Nov 2024.</p><p>- Cleaning air breathers of generator bearing sump.</p><p>- Changed lube oil filters (FS901-1).</p><p>- Cleaning diesel pre-filter (FS934).</p><p>- Changed HP diesel filter (FS936).</p><p>- Changed pilot air supply filter (FS911-1).</p><p>- Cleaned and inspection fuel gas Y-strainer.</p><p>- Cleaned the bleed valve and ignition torch.</p><p>- Replaced fuel injectors 10 Ea. with refurbish spare parts.</p><p>- Performed air assist compressor YPM.</p><p>- Changed air inlet filter.</p><p>- Changed lube oil and lube oil filter.</p><p>- Changed regulator air filters.</p><p><br></p><p>On 6 Nov 2024.</p><p>- Changed Liquid fuel filters (FS935).</p><p>- Removed old air inlet filters and enclosure air filters.</p><p>- Cleaned and inspected air filter casings.</p><p>- Cleaned inside air inlet filter room and air inlet screener.</p><p>- Cleaned inside enclosure air filter room and enclosure screener.</p><p>- Performed welding repair grating of air inlet Pre-filters and enclosure air filters about 30 Ea. by PFO2/N-C.&nbsp;</p><p><br></p><p>On 7 Nov 2024.</p><p>- Reinstalled air inlet Pre-filters M80, M81 and Duracell.</p><p>- Reinstalled enclosure air filters M81&nbsp;.</p><p>- Applied corrosion inhibitor to Variable Guide Vane (VGV) as Solar service bulletin 8.6/112E.&nbsp;</p><p><br></p><p>On 8 Nov 2024.</p><p>- Removed coupling cover.</p><p>- Dissembled spacer coupling.</p><p>- Cleaned and inspected coupling flanges.</p><p>- Performed fuel gas Y-strainer leak test with N2 at approximately 13 Bar. No leaks were found.</p><p><br></p><p>On 9 Nov 2024.</p><p>- Checked DBHE and found results within specification.</p><p>- Performed alignment check of RGB with the generator and found results within specification.</p><p>- Reassembled the coupling spacer and coupling cover.</p><p>- Checked DBHE (Distance Between Hub Ends) Dimension ‘A’ (current)</p><p>Face Top&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; =&nbsp;&nbsp; 411.49 mm.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </p><p>Face Right&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; =&nbsp;&nbsp; 411.56 mm.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p><p>Face Bottom&nbsp;&nbsp;&nbsp; &nbsp;=&nbsp;&nbsp; 411.54 mm.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>        </p><p>Face Left&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; =&nbsp;&nbsp;&nbsp; 411.50 mm.</p><p></p><p>On 10 Nov 2024.</p><p>- Cleaned and inspected frame arrester (FA901).</p><p>- Performed de-mechanical isolation.&nbsp;</p><p>- Performed de- process isolation.</p><p><br></p><p>On 12 Nov 2024.</p><p>- Lined up diesel fuel and engine lube oil to filters.</p><p>- Functionally tested for IGV check and found IGV was fully open at 8 degrees.</p><p>- Performed starting test with gas mode.</p><p>- Functionally tested for changed fuel mode from gas to liquid as found it can not working.</p><p>- Found hydraulic motor (M932)of liquid main pump malfunction and plan to verify on tomorrow.</p><p>- Keep the unit on standby.</p><p><br></p><p></p><p><br></p><p>On 12 Nov 2024.</p><p>Replaced the hydraulic motor (M932) of the main fuel pump due to malfunction.</p><p>- Replaced the hydraulic motor with a new spare part.</p><p>- Found diesel fuel leaking at the lip seal of pump (P931).</p><p>- Replaced the hydraulic pump with a new spare part.</p><p>- Conducted functional and starting tests in liquid mode, it was working properly.</p>', NULL, '2024-11-04 19:39:55', '2024-11-13 19:26:36', 'PTTEP\\Bongkot.turbine-Mech', 'PTTEP\\Bongkot.turbine-Mech', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TG-5630', 'GBN-TG-5630', 'TURBO GENERATOR 3 PACKAGE', NULL, NULL, 'TURBO GENERATOR 3 PACKAGE', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
