  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '12MPM line break function of HOV-80000', 'Electrical & Instrument', 'PM', 'Completed', '2024-11-05', '<p><u><b>Today Activity</b></u></p><p>12MPM functional test line break function of HOV-80000 at ZBV-1.</p><p><br></p><p><u><b>Action</b></u></p><p>- Prepared hand tools and work permit documents.</p><p>- Went to ZBV1,at the time bypass valve was opening for solar installation activities.</p><p>- Opened permit and conducted safety talk.</p><p>- Released pressure from line break tube. (Process isolation)</p><p>- Performed according to Job card.</p><p>- Retightened terminals in line break EX junction box.</p><p>- Checked supply voltage. (24 VDC OK).</p><p>- Checked and cleaned transducer condition.</p><p>- Connected pressure hand pump with transducer.</p><p>- Connected DB9 cable between line guard and laptop</p><p>- Checked as found condition by hand-pump pressure.</p><p>- Found accuracy are out of ranges.</p><p>- Calibrated and checked as left condition.</p><p>- Accuracy was within range and acceptable.</p><p>- After re-assemble line break tubing.</p><p>- Checked LOPC after process de-isolation.</p><p>- No leakage and normal condition.</p><p>- Checked all alarms with CCR. (Not found abnormal)</p><p>- Process is now normal operation.</p><p>- Participated bypass line closing activity.</p><p><br></p>', NULL, '2024-11-05 19:24:23', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-HOV-80000-ASSY', 'ATL-BV1-HOV-80000-ASSY', 'Zawtika Block Valve 1 ASSY', NULL, NULL, 'Zawtika Block Valve 1 ASSY', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
