-- Inserting report ID 20864
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S HVAC unit 2 MCCB trip at AHU room CCR ', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-11-06', '<p><u><b>Today Activity</b></u></p><p>Troubleshoot HVAC unit 2 MCCB trip at AHU room.</p><p><br></p><p><b><u>Action</u></b></p><p>-Prepared work permit documents.</p><p>-Verified the HVAC unit 2 panel.</p><p>-found main MCCB is trip position.</p><p>-checked continuity test with multimeter.</p><p>-found L1 ground fault.</p><p>-check all field equipment termination and magnetic connector, overload condition.</p><p>-found compressor 2 of HVAC unit 2 was ground fault.</p><p>-checked and verified the cable continuity (Cable is OK).</p><p>-disconnected the compressor cable.</p><p>-checked the line to ground fault.</p><p>-found compressor winding ground fault.</p><p>-removed the defective compressor termination.</p><p>-tested run HVAC unit 2 without compressor 2.</p><p>-No MCCB trip and HVAC unit 2 worked only with compressor 3.</p><p>-Found that compressor 1 could not work with high pressure alarm and overload alarm.</p><p>-reduced a few gas pressure.</p><p>-fault was still showing and not working.</p><p><span style="background-color: rgb(255, 255, 0);">-reset the magnetic connector overload relay of compressor 1.</span></p><p><span style="background-color: rgb(255, 255, 0);">-fault alarm was clear and reset the whole system.</span></p><p><span style="background-color: rgb(255, 255, 0);">-HVAC unit 2 are back in service.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Recommendation : Replace with new for compressor 2.</span></p><p><br></p><p><br></p>', NULL, '2024-11-06 17:38:37', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HVAC-AHU2', 'ATL-OC-HVAC-AHU2', 'Air Handling Unit 2', NULL, NULL, 'Air Handling Unit 2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2024-11-06 17:38:37', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2024-11-06 17:38:37', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Inst-Tec', NULL);
