  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'E-3725B heat exchanger replacement.', 'Mechanic', 'CM', 'In Progress', '2024-11-06', '<p><b>&nbsp; &nbsp; &nbsp; &nbsp;E-3725B heat exchanger replacement.</b></p><p>-&nbsp; Preparing hand tools, lifting tools and blind flange</p><p>-&nbsp; Setup lighting tool for remove rich/lean glycol exchanger.</p><p>-&nbsp; Remove rich/lean glycol exchanger out and locate on upper deck PP.</p><p>-&nbsp; Tightening flange 2 inch and torque bolts as per as 69 Nm. (Bolt Dia.5/8”, Nut 27 mm, Socket Wrench #27 mm.).</p><p>- Tightening flange 3 inch and torque bolts as per as 86 Nm. (Bolt Dia.5/8”, Nut 32 mm, Socket Wrench #32 mm.).</p><p>-&nbsp; Housekeeping</p>', '<p class="MsoNormal"><b><span style="font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;
mso-bidi-font-family:&quot;Cordia New&quot;">SPARE PART :<o:p></o:p></span></b></p>

