  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'FGC-1 Startup Troubleshoot', 'Turbine E&I', 'CM', 'Completed', '2024-11-06', '<p>Support FGC#1, start-up unit, and troubleshooting.</p>  <p>&nbsp;- T/S SDV-1201 got valve position discrepancy. Found it positioning coupling was loosened. Then rectified and stroking tested. the valve could be operated on demand.</p>  <p>&nbsp;- T/S SDV-1220 did not open on demand due to XSV-1220B (UCP-Solenoid valve) badly passing through the exhaust ventilation port. After replacing the new solenoid valve and stroking tested. The valve could resume normal operation.</p><p>&nbsp; &nbsp;(Material: 60.98.58.107.3 : SOL VLV BIFOLD FP06P/S1/04/32/NUV)</p><p><br></p><p>&nbsp;- Finally, the FGC#1 could be start-up and onload controlled successfully.&nbsp;&nbsp;</p><p><br></p>', NULL, '2024-11-06 20:17:40', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-C-1210', 'ART-C-1210', 'FEED COMPRESSOR TRAIN 1', NULL, NULL, 'FEED COMPRESSOR TRAIN 1', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
