-- Inserting report ID 20902
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Continue troubleshoot DG-0003 abnormality', 'Electrical & Instrument', 'CM', 'Waiting for Material', '2024-11-07', '<p><b><u>Today’s Activity</u></b></p>  <p>Continue working on the TS DG-03.</p>  <p><b><u>Issue Identified</u></b></p>  <p>The LED optic board PCB assembly(GM74198) was found to be damaged.</p>  <p><b><u>Action Taken</u></b></p>  <p>&nbsp; 1. Performed a function test using the LED optic board from the DG-02.</p>  <p>&nbsp; 2. Verified that the DG-03 operated normally with the DG-02 LED optic board installed.</p>  <p>&nbsp;</p>  <p>The LED optic board in the DG-03 is confirmed to be damaged and needs to be replaced.</p>  <p><b><u>Next Steps</u></b></p>  <p>Plan to order a new LED optic board for the DG-03.</p>  <p>&nbsp;</p>  <p>&nbsp;<b><u style="background-color: rgb(255, 255, 0);">History(06/11/2024)</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp;</span><span style="background-color: rgb(255, 255, 0);">Troubleshoot DG-0003 with engine not start up alarm.</span></p>  <p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">-Started DG-0003</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-found engine run a few second and then stop with alarm.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-RPM was not shown in display panel while engine running.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-found engine not startup alarm.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-Checked control card, no abnormality are found. (in progress)<br><br><br></span></p>  <p><u><b style="background-color: rgb(255, 255, 0);">History&nbsp;</b><b><span style="background-color: rgb(255, 255, 0);">(29 Oct 2024)</span></b></u></p>  <p><span style="background-color: rgb(255, 255, 0);">1M PM ZOC DG-0003 TEST RUN</span></p>  <p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">- Found&nbsp; 12VDC battery was not working properly.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Started with battery starter and run.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Found fuel low alarm, Lube oil alarm and engine no-start alarm. (one by one)</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Top up fuel and reset alarm.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Try to restart DG again.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Engine can start 15 min (run only)</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Not successful for full test run.</span></p>  <p>&nbsp;<br></p>', NULL, '2024-11-07 17:40:16', '2024-11-07 17:45:30', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-DG-0003', 'ATL-OC-DG-0003', 'ZOC Mobile Generator 3', NULL, NULL, 'ZOC Mobile Generator 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2024-11-07 17:40:16', '2024-11-07 17:45:30', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2024-11-07 17:40:16', '2024-11-07 17:45:30', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
END $$;

