-- Inserting report ID 20912
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S HVAC unit 1 MCCB trip at AHU room CCR ', 'Electrical & Instrument', 'CM', 'Completed', '2024-11-07', '<p><u><b>Today Activity</b></u></p><p>Troubleshoot HVAC unit 1 MCCB trip at AHU room.</p><p><br></p><p><b><u>Action</u></b></p><p>-Prepared work permit documents.</p><p>-Verified the HVAC unit 1 panel.</p><p>-checked continuity test with multimeter.</p><p>-checked and verified all field equipment termination and magnetic connectors, overload condition.</p><p>-found that magnetic contactor of compressor 2 are malfunction.</p><p>-found compressor 2 of HVAC unit 2 was ground fault.</p><p>-checked and verified the cable continuity (Cable is OK).</p><p>-disconnected the compressor cable.</p><p>-checked the line to ground fault.</p><p>-found compressor winding ground fault.</p><p><span style="background-color: rgb(255, 255, 0);">-removed the defective compressor termination.</span></p><p><span style="background-color: rgb(255, 255, 0);">-replaced with new magnetic contactor and auxiliary relays.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">-tested run HVAC unit 1 without compressor 2.</span></p><p><span style="background-color: rgb(255, 255, 0);">-No MCCB trip and HVAC unit 1 worked only with one compressor no.3.</span></p><p><span style="background-color: rgb(255, 255, 0);">-HVAC unit 1 are back in service.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Recommendation : Replace defective compressors by new compressors.</span></p><p><br></p><p><br></p>', NULL, '2024-11-07 18:02:59', '2024-11-07 18:14:56', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HVAC-AHU1', 'ATL-OC-HVAC-AHU1', 'Air Handling Unit 1', NULL, NULL, 'Air Handling Unit 1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
