  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S FWP B water jacket heater not working.', 'Electrical', 'CM', 'Under Monitoring', '2024-11-07', '<p>Troubleshooting alarm engine water jacket temperature low.</p><p>- Found alarm at UCP shown "Engine water jacket temperature low" after verified found both heater tripped by temperature switch high high activated (Set at 95''C).</p><p>- Replace a new temperature switch (Both and same set point 95''C) and heater back to normal condition, the warming temperature around 65''C during engine standby.</p><p>- Verify temperature switch which removed after TAHH activated found temperature set correctly and activated at 93''C and 98''C and confirmed the protection system working properly.</p><p><span style="background-color: rgb(255, 255, 0);">- Next action to verify why/how the temperature raise more than 95''C and currently keep monitor the water jacket&nbsp; heater condition during engine standby trip or not.</span></p>', NULL, '2024-11-08 08:40:11', '2024-11-08 08:40:35', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
