  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Commissioning of Solar power system at ZBV2. ', 'Electrical & Instrument', 'OTH', 'Completed', '2024-11-08', '<p><b><u>Today activity&nbsp;</u></b></p><p>Commissioning of Solar power system at ZBV2.&nbsp;</p><p><b><u>Action</u></b></p><p>1.Measure Voltage &amp; Current at BCP-8301</p><p>2.Check voltage and current at the Bus Bar Connection Panel.</p><p>3.Test Ventilation Control Panel (VCP-8301)</p><p>&nbsp;-Confirm proper voltage and functionality of the ventilation system.</p><p>4.Test Indoor Cooling Fan</p><p>5.Test Battery Low Alarms and low low alarm. (AUX 1 &amp; AUX 2)</p><p>&nbsp; &nbsp;-Battery Low Alarm-AUX 1 (23.5V): Alarm should trigger generator start.<br>&nbsp; &nbsp; Ensure generator starts when AUX 1 alarm is triggered.</p><p>&nbsp; &nbsp;-Battery Low-Low Alarm-AUX 2 (22.8V): Alarm should cut off all loads.</p><p>&nbsp; &nbsp; Verify all loads are cut off when AUX 2 alarm activates.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Total 40 solar panels<br>Total 10 NPPT charger controller</span></p><p><span style="background-color: rgb(255, 255, 0);">4 solar panels for 1 NPPT charger controller&nbsp;</span></p><p><br></p><p><br></p>', NULL, '2024-11-08 19:50:52', '2024-11-21 13:47:51', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
