  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pawaris', NULL, 'EXTERNAL', '2024-11-08 21:31:30', CURRENT_TIMESTAMP, 'PTTEP\\art.mechcrane', NULL);
