  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'A-6300 failed to start via Fuel Gas Pilot failure', 'Turbine E&I', 'CM', 'Completed', '2024-11-08', '<p>Detailed troubleshooting process for the TG-3 starting failure due to the “Fuel Gas Pilot failure.</p><p><br></p><ol><li><strong>Identified the Issue</strong>: The solenoid valve (Pilot) (L340-1) was found to be faulty.</li><li><strong>Replaced the Solenoid Valve</strong>: Installed a new solenoid valve with the part number ESM-3201-46-316-H2-XD2-D024 (MESC 20.70.00.636.3).</li><li><strong>Functional Testing</strong>: Used the force signal “L340-1” to ensure the pilot valve was stroking correctly.</li><li><strong>Preparation for Testing</strong>:<ul><li>Closed the fuel gas supply and bled off any remaining gas.</li><li>Isolated the instrument air.</li></ul></li><li><strong>Functional Stroking Testing</strong>: Ensured both fuel gas and instrument air were isolated before testing.</li><li><strong>Start-Up</strong>: Started the TG-3 and controlled the load to 70%.</li><li><strong>Stopped TG-2</strong>: The TG-2 was normally stopped afterward.</li></ol>', NULL, '2024-11-08 21:36:19', '2024-11-08 21:37:01', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-A6300.PK', 'ART-PP-A6300.PK', 'APP MAIN POWER GENERATOR 3 PACKAGE', NULL, NULL, 'APP MAIN POWER GENERATOR 3 PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6300-L340-1', 'ART-A-6300-L340-1', 'VALVE,SOLENOID,PILOT,GAS TORCH SHUT-OFF', NULL, NULL, 'VALVE,SOLENOID,PILOT,GAS TORCH SHUT-OFF', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6300-TE', 'ART-A-6300-TE', 'TURBINE ENGINE (TAURUS 70)', NULL, NULL, 'TURBINE ENGINE (TAURUS 70)', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mongkolsak W.', NULL, 'EXTERNAL', '2024-11-08 21:36:19', '2024-11-08 21:37:01', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tawatchai P', NULL, 'EXTERNAL', '2024-11-08 21:36:19', '2024-11-08 21:37:01', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
