  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace YV-1334 8" 900 ', 'Mechanic', 'CM', 'Completed', '2024-11-08', '<p>Found YV-1334 gas seeping at upstream side.</p><p><br></p><p>On 17 October 2024.</p><p>1. Set up lifting gear and preparation tools for valve replacement.</p><p>2. Remove actuator and accessory.</p><p>3. Measurement and record length of stud bolt both up/down stream side.</p><p>4. Remove YV-1334 for inspection.</p><p>5. Found flange of valve upstream side damage. (Inform by inspection)</p><p>6. Transfer YV-1334 to repair onshore.</p><p>7. Measurement depth of RTJ groove, distance between pipe flange to flange, off set alignment.</p><p><br></p><p>On 6 November 2024.</p><p>1. Reinstall YV-1334 after repair complete.</p><p>2. Tightening torque 1,109 ft.lb. (Standard for heat cycling)</p><p>&nbsp; &nbsp; &nbsp;2.1 Step 1 50% = 560 ft.lb.</p><p>&nbsp; &nbsp; &nbsp;2.2 Step 2 100% = 1,109 ft.lb.</p><p>&nbsp; &nbsp; &nbsp;2.3 Step 3 - 6 = 1,109 ft.lb.</p><p><br></p><p>On 7 November 2024.</p><p>1. Reinstall actuator and accessory.</p><p>2. Housekeeping.</p>', 'More picture hyperlink&nbsp; &nbsp;G:\\ARTShare\\Department Share\\10-Common\\20 - ARTHIT Defective Valve List\\ART Valve Defective - New form\\ART Defective Valve\\YV-1334\\Picture', '2024-11-08 21:53:20', CURRENT_TIMESTAMP, 'PTTEP\\art.mechcrane', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-YV-1334', 'ART-YV-1334', 'SEQUENCING VALVE/ISOLATION VALVE', NULL, NULL, 'SEQUENCING VALVE/ISOLATION VALVE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
