  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S VSH-322781 of TC1 alarm high. ', 'Instrument', 'CM', 'Under Monitoring', '2024-11-09', '<p>Troubleshooting vibration switch VSH-322781 (TC#1) alarm high frequently.</p><p>- Perform measured loop resistance of vibration switch and found it was 4 ohm during contact close and shown status loop open (OL) during contact open.</p><p>- Measured insulation resistance from vibration switch to UCP terminal and found all wiring insulation resistance were more than 55 Mega-ohm.</p><p>- Replaced new completed set vibration switch at setting setpoint around 2G ( Turn clock wise 1/4 round) reference from drawing diagram.</p><p>- Function test by slightly knock then alarm was active at HMI and manual reset at vibration switch, the alarm was cleared as normal.</p>', NULL, '2024-11-09 15:58:29', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Turbine-Tech', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2VSH-322781', 'GBS-2VSH-322781', 'VIBRATION SWITCH HIGH', NULL, NULL, 'VIBRATION SWITCH HIGH', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
