-- Inserting report ID 21018
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Rectified the hunting hydraulic pressure in the W-', 'Turbine E&I', 'CM', 'Completed', '2024-11-10', '<p>Rectified the hunting hydraulic pressure in the W-4850 HYD power pack_ WON: XXXXX</p><p>&nbsp;- Attempted to replace the Relief Unloading Valve, but the hydraulic pressure continued to fluctuate. Re-installed the original valve.</p><p>&nbsp;- Replaced the Check Valve at the driver port (V9A &amp; V9B). The system then stabilized, with no further pressure fluctuations.</p><p>&nbsp;- Conducted stroking tests on the WHRU damper, which were satisfactory to the CCR, achieving 40/30 seconds for fully open and fully closed positions.</p><p>&nbsp;- The W-4850 is now operational, and the FGC#2 is ready to start.</p><p>&nbsp;- Noted, Both PSV-4850RV-1 have been confirmed setpoint about 128 barg (Certificated Tag 130 Barg).</p><p>          </p><p>(Both PSV-4850RV-1 and Relief Unloading valve should be recertified and prepared to be certified as available spare)</p>', NULL, '2024-11-10 20:43:58', CURRENT_TIMESTAMP, 'PTTEP\\TawatchaiP', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-W-4850', 'ART-W-4850', 'WHRU-FEED GAS COMPRESSION TURBINE TRN 2', NULL, NULL, 'WHRU-FEED GAS COMPRESSION TURBINE TRN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PSV-4850RV1', 'ART-PSV-4850RV1', 'PRESSURE SAFETY VALVE', NULL, NULL, 'PRESSURE SAFETY VALVE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
