  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG-2,Verified Fire syst Trouble_Strb-Horn loop', 'Turbine E&I', 'CM', 'Completed', '2024-11-10', '<p>Verified the possible root cause of the fire system trouble on TG-2, which was related to a loop short circuit in the strobe light-1 alarm. (WON: XXXX )</p><p>&nbsp;- The alarm was cleared, and TG-2 is now available and ready to start.</p><p>&nbsp;- No significant water ingress was found inside the terminal box located within the TG-2 package enclosure.</p>  <p>&nbsp;- Found droplets of water mist inside the strobe light-1 and horn housing located above the enclosure outside the package. Rectified by cleaning and drying with contact cleaner, and confirmed all seal O-rings were in good condition. Applied non-hardening grease on housing bolts and the covering flame path.</p>  <p><br></p><p>Finally, both the strobe light and horn were properly working via fire alarm simulation testing.</p>  <p>The TG-2 is available to start without any remaining alarms.</p>', NULL, '2024-11-10 20:55:03', CURRENT_TIMESTAMP, 'PTTEP\\TawatchaiP', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6200-FIG20202', 'ART-A-6200-FIG20202', 'FIRE SYSTEM CONTROL STATION PANEL', NULL, NULL, 'FIRE SYSTEM CONTROL STATION PANEL', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
