  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Test run G-9110 with full load by original relays', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-11-17', '<p><span style="background-color: rgb(255, 255, 0);">Test run Gas Generator G-9110 with full load by original control relays.</span></p><p>1.Reinstalled original control relays to G-9110 and test run with full load.</p><p>2.After running with full load about 3hr, Gas Generator G-9110 trip by Engine &lt;RPM alarm.</p><p>3.So, we selected most suspected five control relays and try to reinstalled to G-9110 from G-9120.</p><p>4.After replacement completed, test run gas generator G-9110 with full load and monitoring by night shift ZMS Operator for the whole night.Generator is still running fine.</p><p>5.Under Monitoring.</p><p><br></p>', NULL, '2024-11-18 06:24:55', '2024-11-18 06:26:24', 'PTTEP\\ZMS.MTN-Tech', 'PTTEP\\ZMS.MTN-Tech', false, 'ATL') RETURNING id INTO new_report_id;
