  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Crane AWp-39 Can''t operate', 'Electrical', 'CM', 'In Progress', '2024-11-19', '<p>T/S crane AWP-39 can''t operate all function.</p><p>- Check PLC condition and trial Emergency key bypass after that function test found still can''t operate.</p><p>- Check alarm condition found acknowledge all completed.</p><p>- Check all of solenoid operetion found some one resistance more than of solenoid manofold. SV2=358 Ohm. and other measure about 18 Ohm.</p><p>- Check pressure control pilot of joy strick found no pressure. ( Normal operation about 30 Bar.)</p><p>- Confirm function test by manual force found pressure control pilot reading 30 Bar. And function test all of condition found normally operation.&nbsp;</p><p>- Swap solenoid valve from SV12 to SV2 and&nbsp; monitor control pressure found 30 Bar and crane normal operate except Slew Right function can''t operate due to SV12 it is Slew Right function.</p><p>- Now crane condition can be operate all of function except SLEW RIGHT only waitting reaplace solenoid valve.</p><p>-&nbsp; Solenoid valve Brand: FAVELL FAVCO Model : AHFX-0004-3000</p>', '\\\\pttep.com\\DFSRootART\\ARTShare\\Selective Access\\02-PAT-M\\02-PAT-M_El\\04 - Electrical_Instrument\\18-EI Pictures Database\\2 AWP\\AWP-39\\Crane\\Control Pressure Solenoide Damaged 19 Nov 24', '2024-11-19 19:48:38', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-WP39-3X-3973.PK', 'ART-WP39-3X-3973.PK', 'PEDESTAL CRANE ART-WP39', NULL, NULL, 'PEDESTAL CRANE ART-WP39', 'ART-WP39', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Meechai D. Supakorn S.', NULL, 'EXTERNAL', '2024-11-19 19:48:38', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL);
END $$;

