-- Inserting report ID 21425
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To replace RO Membrane water maker ', 'Mechanic', 'CM', 'Completed', '2024-11-19', '<p align="left"><u><b>18 November 2024</b></u><br>- Remove retaining ring (No.10)and bearing plate(No.2) 4set (Include Sealing Plate(No.3), Permeate&nbsp; &nbsp; &nbsp; Port(No.7), Adapter(No.15) and Trust cone(No.16)) out of Shell.</p>- Remove 4 RO Membrane (2 Element of upper tube and 2 Element lower tube) and inspect.<p align="left">-&nbsp; During the inspection, it was found that there is trace of dirt adhering to the top and bottom&nbsp;&nbsp;&nbsp;&nbsp; of the membrane.<br></p><p align="left">-&nbsp; Reassembly bearing plate (No.2) 4set (Include Sealing Plate(No.3), Permeate Port(No.7), Adapter(No.15) and Trust cone(No.16)) and inspect. All part and O-ring kit not found abnormal.<br>- Replace Ro membrane (MESC: 42.40.08.024.3) Upper tube 2element and install bearing plate (No.2) 4set (Include Sealing Plate (No.3), Permeate Port (No.7), Adapter (No.15) and Trust cone (No.16)) lock plate with retaining (No.10)<br>- Process de-isolation and Electrical de-isolation. Line up process breath air and leak test, not found leak&nbsp; &nbsp;&nbsp;</p><p>-&nbsp; Test run and measure conductivity value.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Total&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; = 1013 µS/cm (HH=1000)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Upper tube = 384 µS/cm</p><p align="left">      &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Lower Tube = 1515 µS/cm<br><b><u>19 November 2024</u></b><br>- Remove retaining ring (No.10)and bearing plate(No.2) 4set (Include Sealing Plate(No.3), Permeate Port(No.7), Adapter(No.15) and Trust cone(No.16)) out of Shell.<br>- Remove 2 RO Membrane (Lower tube) and replace New Membrane element.&nbsp; &nbsp;&nbsp;</p><p>-&nbsp; Test run and measure conductivity value.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Total&nbsp; &nbsp; &nbsp; &nbsp;= 344 µS/cm (HH=1000)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Upper tube = 558 µS/cm</p><p align="left">      </p><p align="left">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Lower Tube = 192 µS/cm<br>- Operated flush 12 Hrs.<br>- Clean working area and housekeeping.</p>', NULL, '2024-11-20 14:58:41', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-4850', 'GBS-2X-4850', 'WATER MAKER PACKAGE TRAIN B', NULL, NULL, 'WATER MAKER PACKAGE TRAIN B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
