-- Inserting report ID 21427
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify UPS Tripped & SCADA system freeze at  ZBV1', 'Electrical & Instrument', 'CM', 'Completed', '2024-11-20', '<p><b><u>Today''s Activity:</u></b></p><p><b><u><br></u></b></p><p>Verified SCADA system freeze at ZBV1.&nbsp;&nbsp;</p><p><b><u>Findings:</u></b></p><p>1. Generator G8010 is running, and the air-conditioning and ventilation fan are operational.&nbsp;&nbsp;</p><p>2. DC power breakers at the DCUPS panel were tripped.&nbsp;&nbsp;</p><p>&nbsp; &nbsp;- The SCADA system receives DC power from the DCUPS.&nbsp;&nbsp;</p><p><b><u>Actions Taken:</u></b></p><p>1. Attempted to reset the breaker but could not reset or turn it on.&nbsp;&nbsp;</p><p>2. Reset the GUTOR HMI controller board.&nbsp;&nbsp;</p><p>&nbsp; &nbsp;- After resetting the HMI controller board, all DC UPS breakers could be turned on.&nbsp;&nbsp;</p><p><b><u>Results:</u></b></p><p>- DC power is now available, and the SCADA system is back to normal.&nbsp;&nbsp;</p><p><br></p><p><b><u><br></u></b></p><p><br></p>', NULL, '2024-11-20 15:17:43', '2024-11-21 13:47:12', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010-PACKAGE', 'ATL-BV1-G-8010-PACKAGE', 'Gen, ZBV1 Diesel Generator package1', NULL, NULL, 'Gen, ZBV1 Diesel Generator package1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8020-PACKAGE', 'ATL-BV1-G-8020-PACKAGE', 'Gen, ZBV1 Diesel Generator package2', NULL, NULL, 'Gen, ZBV1 Diesel Generator package2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
