-- Inserting report ID 21573
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Moisture Transmitter MIT-5230 reading dif 5240', 'Instrument', 'CM', 'In Progress', '2024-11-24', '<p>T/S Moisture Transmitter MIT-5230 reading difference with MIT-5240 (after received spare part)</p><p>- As found MIT-5230 reading -60 ''C (Dryer D-5230 unit stop) and MIT-5240 reading -73 ''C (Dryer D-5240 running)</p><p>- Measure loop current by Clamp Amp, as found MIT-5230 was 9.45 mA, MIT-5240 was 7.57 mA</p><p>- Disconnect and simulated current from ME- which found Moisture Indicator reading ;</p><table class="table table-bordered"><tbody><tr><td><font color="#3984c6">mA</font></td><td><font color="#3984c6">MIT-5230</font></td><td><font color="#3984c6">MIT-5240</font></td><td><font color="#3984c6">Unit</font></td></tr><tr><td>4</td><td>-99.9&nbsp;</td><td>-99.8&nbsp;</td><td>''C</td></tr><tr><td>8</td><td>-70.0</td><td>-69.9</td><td>''C</td></tr><tr><td>12</td><td>-40&nbsp;</td><td>-39.9</td><td>''C</td></tr><tr><td>16</td><td>-10&nbsp;</td><td>-10</td><td>''C</td></tr><tr><td>20</td><td>20</td><td>19.9</td><td>''C</td></tr></tbody></table><p>- Replaced both new Moisture Transmitters for verify dew point reading (refer to reading with both As Found&nbsp; transmitters)</p><p>- As Left dewpoint temperature are decreasing by MIT-5230 is -51''C and MIT-5240 is -53.4''C</p><p>- Keep monitor for settle temperature.</p><p><br></p><p>Refer history</p><p>9/11/2023</p><p>- As found reading of MIT-5230 is -8.1 Deg C while MIT-5240 is -43.7 Deg C.</p><p>- Swop input wiring from MIT-5240 to MIT-5230 and found MIT-5230 is reading -37.5 Deg C.</p><p>- Simulate miliamp input to MIT-5230 and found it was reading correctly (4-20 mA = 20&nbsp; to -100 Deg C.)</p><p>- Simulate miliamp input to MIT-5240 and found it was reading not correctly by 4 mA = under range, 20 mA= 2.3 Deg C.</p><p>Note : DCS scalling 20 - (-100) Deg C.</p><p>- Recalibrate MIT-5240 (4-20 mA = 20 to -100 Deg C.)</p><p>- Cleaned sensor guard, flow rotameter of MIT-5230 amd MIT-5240 due to some oil contaminate.</p><p>- Adjust flow rate for both transmitter at 10 L/Min.</p><p>- Connect temporary tube from D-5230 to MIT-5240 for compare reading value with MIT-5230.</p><p>- To be continue on tomorrow.</p><p><br></p><p>11/11/2023</p><p>- Connected nitrogen to perform as found reference reading of MIT-5230 and MIT-5240 and found MIT-5240 is -34.9 Deg C and&nbsp; &nbsp;MIT-5240 is -40.1 Deg C.&nbsp;</p><p>- Tried to reading nitrogen dew point via automatic dew point meter but it couldn''t reading, suspected the meter was malfunction.</p><p>- Online process from D-5240 to both mositure transmitter and found MIT-5240 is -40.2 Deg C and MIT-5240 is -46.5 Deg C. Keep monitor</p>', '<p>Previous History:</p><p>http://arthit-sshe-app:81/eihistory/</p><p><br></p><p>Photo:</p><p>\\\\pttep.com\\DFSRootART\\ARTShare\\Selective Access\\02-PAT-M\\02-PAT-M_El\\04 - Electrical_Instrument\\18-EI Pictures Database\\1 APP\\Air Compressor-Dryer_52xx</p>', '2024-11-24 09:06:01', '2024-11-24 17:35:25', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-MAH-5230', 'ART-MAH-5230', 'MOISTURE TRANS,AIR DRYER D-5230/D-5235', NULL, NULL, 'MOISTURE TRANS,AIR DRYER D-5230/D-5235', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-MAH-5240', 'ART-MAH-5240', 'MOISTURE TRANS,AIR DRYER D-5240/D-5245', NULL, NULL, 'MOISTURE TRANS,AIR DRYER D-5240/D-5245', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-ME-5230', 'ART-ME-5230', 'MOISTURE ANALYSER,AIR DRYER D-5230,5235', NULL, NULL, 'MOISTURE ANALYSER,AIR DRYER D-5230,5235', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
