-- Inserting report ID 21659
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S WHRU-4850 hydraulic pressure malfunction', 'Turbine E&I', 'CM', 'Completed', '2024-11-25', '<p>Work activity on 12 Nov-25 Nov 2024</p><p>-Troubleshooting on WHRU-4850 HPPU hydraulic malfunction.</p><p>Found unloading valve working abnormal running frequency.</p><p>-Replaced unloading valve V1 and subplate V14</p><p>-Replaced solenoid valve V8,V9A/B and V10A/B&nbsp;</p><p>-Function test still abnormal.</p><p>Verify hydraulic leak found leak at port T of subplate to tank from internal spoon of solenoid.</p><p>-Found hydraulic oil contaminate.</p><p>-Changed new hydraulic oil and function test again but found still abnormal unloading valve frequently working.</p><p>-Still found hydraulic oil contaminate&nbsp;</p><p>-Verified ACC2 acumulator found lost of precharge pressure and then replaced accumulator.</p><p>-After replaced ACC2 and function test unloading valve still abnormal.</p><p>-Swap solenoid control set subplate,V9A/B,V10A/B with WHRU-4900 of TG#2&nbsp;</p><p>-After swap solenoid from TG#2 and function test found unloading valve still abnormal.</p><p>-Verify hydraulic oil found Air inside the hydraulic oil.</p><p>-Perform cleaned up hydraulic tank,All tubing and flush actuator control line tubing.</p><p>-Replace hydraulic pump,Tank suction filter,Discharge filter and chrage ACC1 Fail safe accumulator to 60 bar due to found pressure loss remain 30 bar.</p><p>-After that function test run found hydraulic normal nor contaminate or air tap.</p><p>-Setting pressure of Fail safe accumulator at 110 bar and operating pressure is about 104-105 bar but still</p><p>found unloading valve working about 10 sec per time it better than before.</p><p>-Still found internal leak inside spoon solenoid to Tank but leak rate is less than before.</p><p>-Recalibrat Ex200 and Function stroking test damper found fully open 40 sec and fully close 22 sec.</p><p>-Unit working normal but unloading valve frequently action 1 time per 10 second.</p><p><br></p>', NULL, '2024-11-25 22:00:41', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-W-4850', 'ART-W-4850', 'WHRU-FEED GAS COMPRESSION TURBINE TRN 2', NULL, NULL, 'WHRU-FEED GAS COMPRESSION TURBINE TRN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mongkolsak W.', NULL, 'EXTERNAL', '2024-11-25 22:00:41', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Worapong A.', NULL, 'EXTERNAL', '2024-11-25 22:00:41', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL);
