-- Inserting report ID 21664
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S TR-4670 cannot control by DCS', 'Automation', 'CM', 'Completed', '2024-11-14', '<div>T/S TR-4670 rectifier A of hypochlorinator cannot control current by DCS.</div><div>- Verified loop 4-20 mA from DCS not present at UCP.</div><div>- Checked loop 4-20 mA at marshaling cabinet no analog output.</div><div>- Verified excel data base of DCS analog output. Found point of loop control shown terminal 171-172.</div><div>- At marshaling cabinet wiring terminal 173-174.</div><div>- Checked history. Found the original analog output was used at terminal 171-172. During PLC upgrade channel output 171-172 was defected. Then change channel output to 173-174.</div><div>- After that during FSD2024. We are upgrade new DCS. Vender change card to new model. And download backup project to controller. The analog output channel for hypochlorinator change back to 171-172. It was affected to CRO cannot control current of TR-4670 rectifier A.</div><div>- Performed rewiring analog output channel from 173-174 to 171-172.&nbsp;</div><div>- Start unit and function test.</div>', 'G:\\ARTShare\\Selective Access\\02-PAT-M\\02-PAT-M_El\\02 - Automation\\1.DOCUMENT FOR HAND OVER\\2023_2024\\Hypo\\Hypo cannot command by DCS', '2024-11-25 22:56:19', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-4670', 'ART-A-4670', 'HYPOCHLORINATOR PACKAGE', NULL, NULL, 'HYPOCHLORINATOR PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Piriyut K.', NULL, 'EXTERNAL', '2024-11-25 22:56:19', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL);
