  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify the KP 30+300 CCTV malfunction', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-11-26', '<p><b><u>Today Activity</u></b></p><p>Verify and Troubleshoot KP30+300 CCTV malfunction.</p><p><br></p><p><b><u>Findings:</u></b></p><p>The battery, inverter, and solar power system are functioning properly.</p><p><b><u>Actions Taken&nbsp;</u></b></p><p>Exercised all breakers and restarted the power system.</p><p><span style="background-color: rgb(255, 255, 0);">The CCTV system is now working, and the CCR can view the CCTV feed.</span></p><p><br></p><p><b><u>Additional Issues Found</u></b></p><p>1. One ventilation fan is not running.</p><p>2. The wire terminal on the temperature module is loose.</p><p><b><u><br>Action for additional issues</u></b></p><p>Checked the ventilation fan system and found that the fan is damaged.</p><p>Reinstalled the terminal on the temperature module with a cable lug.</p><p><br></p><p><b><u>Plan</u></b></p><p>Plan to replace the damaged fan with a new one.</p><p><br></p>', NULL, '2024-11-26 15:55:42', '2024-11-26 17:12:01', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
