  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed monthly PM on G-8020', 'Mechanic', 'PM', 'Completed', '2024-11-28', '<div>Performed monthly PM for G-8020</div><div><br></div><div>Action:</div><div><br></div><div>- Checked and cleaned the air filter and its housing.</div><div><br></div><div>- Checked the air service indicator.</div><div><br></div><div>- Checked the radiator cap condition.</div><div><br></div><div>- Checked the coolant level.</div><div><br></div><div>- Drained and topped-up lube oil( Dynamic+ - 10L).</div><div><br></div><div>- Replaced the lube oil filter.</div><div><br></div><div>- Checked the radiator fan belt.</div><div><br></div><div>- Checked and tightened the loosening bolts and nuts.</div><div><br></div><div>- Housekeeping and perform a test run.</div><div><br></div><div>- Recorded the parameters and kept it online.</div><div><br></div><div><br></div><div><br></div><div>Required Tools</div><div><br></div><div>- Refer to BV PM Toolists which is attached to the cabinet in the toolroom.</div>', NULL, '2024-11-28 15:44:53', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
