  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neymar', NULL, 'EXTERNAL', '2024-11-28 15:44:53', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
