  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To perform 6MPM regeneration gas cooler', 'Mechanic', 'PM', 'Completed', '2024-11-28', '<p>- Change lube oil gear box about 18.9 liters (Mobil SCH 630).</p><p>- Measure blades angle about 16.5 degree.</p><p>- Check blades clearance between blade edge and casing (plenum)&nbsp;</p><p>&nbsp; &nbsp; East = 14 mm., West = 14 mm., South = 13mm., North = 14 mm.</p><p>- Check blades condition.</p><p>- Check driving coupling condition.</p><p>- Change driving coupling lubrication.</p><p>- Re-tight gearbox and motor holding down bolts.</p><p>- Function test.</p><p><br></p><p><br></p><p><br></p>', NULL, '2024-11-28 16:07:59', '2024-11-29 17:34:16', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
