-- Inserting report ID 21875
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verified TG-1 Engine Bearing 2X spike', 'Turbine E&I', 'CM', 'Completed', '2024-11-30', '<p>Verified that TG-1 Engine Bearing 2X showed a spike reading at 70% load sharing.</p><ul><li><br></li><li>After TG-1 had been stopped and cooled down normally:</li><li><ul><li>&nbsp;- Swap the sensor cables between bearings 2X and 2Y.</li><li>&nbsp;- Start up and load the unit to record the vibration values for both bearings 2X and 2Y.<ul><li>&nbsp; &nbsp;-&nbsp; During condition monitoring, TG-1 and TG-2 shared the load in ISOCH mode at 3.2 MW and&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 0.9 MW, respectively, while TG-3 was onloaded in island mode (DROOP) at approximately </li><li>&nbsp; &nbsp; &nbsp; 0.9 MW. This monitoring period took about 2.5 hours, from 14:00 to 16:30, but no spike&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; readings were exhibited.</li><li>&nbsp; &nbsp;- Then, adjusted the load sharing of TG-1 and TG-2 to about 2.0 MW each, while TG-3 maintained </li><li>&nbsp; &nbsp; &nbsp; a fixed load of 1.0 MW.</li><li>-&nbsp; Since no spike readings were exhibited on bearings 2X and 2Y, TG-3 was voluntarily stopped, </li><li>&nbsp; &nbsp;and the load sharing between TG-1 and TG-2 was maintained as usual. Monitoring continued.</li><li>-&nbsp; The current load sharing is TG-1 at 3.3 MW and TG-2 at 1.7 MW.</li><li>----------------------------------</li><li>The probe sensor probe 2X and 2Y could measure their impedance at 8.4 ohm and 8.7 ohm.</li><li>Both probes and extension cables were open loop insulation.</li></ul></li></ul></li></ul><p><ul></ul></p><p><ul></ul></p><p><br></p><ul><li><ul><li></li></ul></li></ul>', NULL, '2024-11-30 18:33:29', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6100', 'ART-A-6100', 'MAIN POWER GENERATOR PACKAGE', NULL, NULL, 'MAIN POWER GENERATOR PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tawatchai', NULL, 'EXTERNAL', '2024-11-30 18:33:29', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Meechai', NULL, 'EXTERNAL', '2024-11-30 18:33:29', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL);
