  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-CCVT-26-400', 'GBN-CCVT-26-400', 'CLOSED CYCLE VAPOR TURBO GENERATOR', NULL, NULL, 'CLOSED CYCLE VAPOR TURBO GENERATOR', 'GBN-WP16', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Theeraphong', NULL, 'EXTERNAL', '2024-12-01 21:57:15', '2024-12-01 21:57:31', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitas', NULL, 'EXTERNAL', '2024-12-01 21:57:15', '2024-12-01 21:57:31', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead');
