  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S solenoid XV-5640B deluge valve malfunction', 'Instrument', 'CM', 'Completed', '2024-12-03', '<p>&nbsp;<b>T/S solenoid XV-5640B deluge valve malfunction </b>(bridge APP to AWP01)</p><p>- Forced signal on XSV-5640B and measured voltage at marshalling cabinet ISP-PP-255, TB-DO5: 167 and 168 about 24.91 Vdc.</p><p></p><p></p><p></p><p><br></p><p>- Measured solenoid coil B resistance about 135.7 ohm, coil A resistance 138.3 ohm and reference with new solenoid coil 128 ohm.</p><p></p><p><br></p><p>- Measured voltage at solenoid valve, found 24 Vdc as normal, suspected solenoid valve stuck.</p><p>- Replaced with new solenoid valve and function tested with CCR.</p><p></p><p><br></p><p></p><p></p><p></p>', '\\\\pttep.com\\DFSRootART\\ARTShare\\Selective Access\\02-PAT-M\\02-PAT-M_El\\04 - Electrical_Instrument\\18-EI Pictures Database\\1 APP\\Deluge Valve\\Deluge valve XV-5640B 20241203', '2024-12-03 14:05:07', '2024-12-03 18:27:41', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
