BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 6MPM waste water treatment package', 'Mechanic', 'PM', 'Completed', '2024-12-05', '<p>Sewage Treatment System</p><p><b>Air Blower (B-8910A/B)</b></p><p>-Check the air suction filters.</p><p>-Check the air blower belt tension &amp; condition.(Found belt loose a little)</p><p>&nbsp;Adjust the air blower belt tension.</p><p>-Check the blower pulley alignment.</p><p>-Check &amp; drain the gear oil.</p><p>-Topped up the new gear oil by about 0.5 liters.(PTT GL-5)</p><p>-Inject grease to bearing about 3 strokes. (EP-2)</p><p>-Check all mounting bolts &amp; nuts for tightness.</p><p>-Check the tightness of the shaft coupling lock bolt</p><p>-Housekeeping &amp; clean the air blower package.</p><p>-Perform air blower test running &amp; record the parameters..(No abnormality found)</p><p><b>Submersible Pump (P-8935A/B,P-8955,P-8965</b>)</p><p>-Removed the discharge pipe union connection &amp; lifted the submersible pump.</p><p>-Check &amp; Clean the submersible pump unit inlet.</p><p>-Put the submersible pump back to normal position &amp; reinstall the discharge pipe union connection.</p><p>-Perform submersible pump test running &amp; record running voltage, and ampere.(No abnormality found)</p><p><br></p><p>Tools require</p><p>-Belt wrench</p><p>-Water pressure jet</p><p><br></p><p>.</p>', NULL, '2024-12-05 15:40:13', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ZOC-UTL-SEWAGE-TREAMENT', 'ZOC-UTL-SEWAGE-TREAMENT', 'Sewage Treatment Package', NULL, NULL, 'Sewage Treatment Package', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Shane', NULL, 'EXTERNAL', '2024-12-05 15:40:13', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neymar', NULL, 'EXTERNAL', '2024-12-05 15:40:13', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
