-- Inserting report ID 22072
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'DEP-6220 Fire water pump Perform mechanic 6M PM.', 'Mechanic', 'PM', 'Complete', '2024-12-05', '<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<b> DEP- 6220 Perform 6PM.</b></p><p><b>&nbsp; Diesel engine.</b></p><p>&nbsp;- General inspection of engine for debris, foreign objects or broken fittings.</p><p>&nbsp;- Checked the condition of gauges.&nbsp;</p><p>&nbsp;- Checked engine crankcase oil level.</p><p>&nbsp;- Cleaned engine crankcase breathers.</p><p>&nbsp;- Checked Belt tension.</p><p>&nbsp;- Checked and lubricated all linkages.</p><p>&nbsp;- Checked engine crank oil level.</p><p>&nbsp;<b>Cooling system.</b></p><p>&nbsp;- Checked engine coolant level.</p><p>&nbsp;- Inspect zinc rod in row water system.</p><p>&nbsp;- Replaced zinc rod=2 ea.</p><p>&nbsp;- Checked water cooling PH = 9</p><p>&nbsp;- Visual inspected coolant line connection and hoses.</p><p>&nbsp;- Visual inspected coolant pump.</p><p>&nbsp;- Cleaned cooling water strainer and replaced new gasket (CAF).</p><p>&nbsp;<b> Coupling/Universal join.</b></p><p>&nbsp;- General inspection for coupling element cranks, normal condition. (Wrench # ¾” and 1/2:”)</p><p>&nbsp;- Lubricate universal joint. (Grease EP-2)</p><p>&nbsp;- Inspected pinion starter both sides.</p><p>&nbsp;- Cleaned speed censer.</p><p></p><p>&nbsp;- Checked bolt tightness (Specification 240 Nm.)</p><p>&nbsp;<b> Fuel system.</b></p><p>&nbsp;- Checked for leak, keep fuel tank full, normal operation.</p><p>&nbsp;- Drained sediment and water from fuel tank.</p><p>&nbsp;- Cleaned the fuel primary filter. (Wrench # 15/16”)</p><p></p><p>&nbsp;- Clean and inspect the flame arrestor of diesel day tank. (Pipe wrench # 24”)</p><p><b>&nbsp;<u>Air induction system.</u></b></p><p>&nbsp;- Inspected air inlet system. (Flat screwdriver)</p><p>&nbsp;- Cleaned air inlet filter.</p><p>&nbsp;- Visual inspected turbo charger clearance was=0.50MM.</p><p>&nbsp;<b><u>Air starting system</u>&nbsp;</b></p><p><u></u></p><p></p><p>&nbsp;- Checked air cylinder pressure and drain condensate.</p><p>&nbsp;- Replaced lubricating oil.&nbsp;&nbsp;</p><p>&nbsp;- Checked and Cleaned air inlet filter.</p><p></p><p>&nbsp;- Checked belt tension and wear, normal condition.</p>', '<p><span style="font-weight: 700;"><span style="font-size: 11pt; font-family: &quot;Times New Roman&quot;, serif;">SPARE PART.</span></span></p><p><span style="text-indent: -0.25in; font-family: &quot;Times New Roman&quot;; font-size: 7pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; line-height: normal;">&nbsp; -&nbsp;</span><span style="text-indent: -0.25in; font-size: 11pt; font-family: &quot;Times New Roman&quot;, serif;">Rust remover WD-40&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; MESC: 88.98.15.001.9&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;1 Can.</span></p><p><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt; text-indent: -0.25in;">&nbsp;- Safety solvent Crown 8060</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt; text-indent: -0.25in;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt; text-indent: -0.25in;">MESC: 36.56.13.715.3</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt; text-indent: -0.25in;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt; text-indent: -0.25in;">&nbsp;&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 11pt; text-indent: -0.25in;">1 Can.</span></p><p><span style="font-size: 11pt; font-family: &quot;Times New Roman&quot;, serif;">&nbsp;- Corrosion inhibitor plug, P/N 3606K3&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; MESC: 19.09.45.205.3&nbsp; &nbsp; &nbsp; &nbsp; 2&nbsp;Ea.&nbsp;</span></p><p><span style="font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif;">&nbsp;- Compressor lube oil&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;MESC: 87</span><font face="Times New Roman, serif"><span style="font-size: 16px;">.24.95.186.9</span></font><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 12pt;">&nbsp; &nbsp;&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; font-size: 12pt;">0.7 Liters.</span></p>', '2024-12-05 15:41:41', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL, false, 'G2N') RETURNING id INTO new_report_id;
