  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Voluntaily stopped TG-1 to revert 2X,2Y connection', 'Turbine E&I', 'CM', 'Completed', '2024-12-07', '<p>Changeover Report: TG-1 to TG-3</p><p>Load Distribution:</p><ul><li>70% on TG-2</li><li>30% on TG-3</li></ul><p><br></p><p>Timeline:</p><ul><li>16:10:&nbsp;Load sharing between TG-2 and TG-3 completed.</li><li>16:40:&nbsp;TG-1 stopped for cooldown.</li></ul><p><br></p><p>Notes:</p><ul><li>Prior to the swap, TG-1 was monitored for spike readings on Bearing 2X and 2Y. Despite the initial spike on 2X, both 2X and 2Y readings remained normal, even with TG-1 operating at approximately 70% load (around 3.4 MW).</li><li>After consulting with K. Nopharut (HhooHam), we decided to revert to the original connection.</li><li>TG-1 was subsequently stopped voluntarily upon request.</li></ul>', NULL, '2024-12-07 20:58:46', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6100', 'ART-A-6100', 'MAIN POWER GENERATOR PACKAGE', NULL, NULL, 'MAIN POWER GENERATOR PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
