-- Inserting report ID 22193
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG-1 Verified Brg 2X (VIB) spike reading ', 'Turbine E&I', 'CM', 'In Progress', '2024-12-08', '<p>Please find the attachment for more details.</p><p>Historical Context:</p><ul><li>Since the end of October 2024, TG-1''s Brg 2X has shown a spike reading.</li><li>Verification steps included checking probes and extension cable impedance against manufacturing specifications.</li><li>We swapped the signal cables between 2X and 2Y, assuming the spike reading would move to 2Y if the sensor was deteriorating or aging due to long service.</li><li>However, no significant spike readings were observed on either 2X or 2Y.</li><li>After consulting with Package Engineer K. Noppharut (Mhoo Ham), we decided to revert the connections to their original state.</li></ul><p><br></p><p></p><p><br></p><p>Today''s Activities:</p><ol><li>Swapped back the sensor probe cables between bearings 2X and 2Y after verifying the signal vibration at 70% load.</li><li>After reverting both signals to their original connections:<ul><li>TG-1 and TG-2 shared an electrical generation load of approximately 70% and 30%, respectively. Continue monitoring the TG-1 engine vibration systems for further conditions.</li></ul></li><li>TG-3 underwent a voluntary overspeed tripping test. After the test, the engine was manually cranked for cooling down to ensure TG-3 is ready to start.</li><li><br></li><li></li></ol>', NULL, '2024-12-08 17:50:07', '2024-12-08 17:52:23', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6100', 'ART-A-6100', 'MAIN POWER GENERATOR PACKAGE', NULL, NULL, 'MAIN POWER GENERATOR PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tawatchai', NULL, 'EXTERNAL', '2024-12-08 17:50:07', '2024-12-08 17:52:23', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
END $$;

