  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Hazard Hunt_Fixed Gas seeping on DPIT-2 filter2nd', 'Turbine E&I', 'CM', 'Completed', '2024-12-08', '<p>Hazard Hunt: Gas Leak at SGC#1 Seal Gas Condition Skid (Please find attachment for more info.)</p><p><br></p><p><b>Summary</b>:&nbsp;The site production operator reported a gas leak at the SGC#1 seal gas condition skid.</p><p><br></p><p><b>Findings</b>:&nbsp;Upon inspection, a gas leak was found at the fitting of the DPIT-2 (high-side impulse line tubing).</p><p><br></p><p><b>Action Taken</b>:&nbsp;The leak was rectified under a Cold Permit to Work (PTW) by replacing the impulse line tubing. The fitting was found to be excessively tightened, which caused the leak.</p><p></p><p><br></p><p></p><p>Confirmed no leaking after replacing the tubing.</p><p></p><p>&nbsp;</p>', NULL, '2024-12-08 20:28:37', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
