  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'TawatchaP.', NULL, 'EXTERNAL', '2024-12-08 20:28:37', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL);
