-- Inserting report ID 22211
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2TE-332870 A/B high alarm ', 'Instrument', 'CM', 'Completed', '2024-12-09', '<p>TC#2 Control and instrument Job task 9 Dec 2024&nbsp; tentatively 02:00&nbsp; – 10:00&nbsp; hrs.</p><p>Remove existing speed sensor SE-332870 A/B and 2TE-332870 A/B from the clutch assembly&nbsp; to disassembly Engine starter part. &gt;&gt;Done</p><p>Mech team remove the clutch assembly&nbsp; &gt;&gt;Done</p><p>Replace speed sensor SE-332870 A/B by new sensor (come with new clutch module) and setting by plate adjustment. &gt;&gt;Done</p><p>Performed as found temp reading for reference base line by temp simulator. &gt;&gt;Done as found both sensors response to temp normally (use temp bath to test up to 100 DegC)</p><p>Check all connections of speed sensor and temp sensor. &gt;&gt;Done</p><p>Replace IO module MTL8000 (2 unit, new spare module) &gt;&gt;Done</p><p>Replace new temp sensor A or B and function test by temp simulator. (replace only one sensor, only one spare available) &gt;&gt;Done replace sensor B</p><p>Reuse temp sensor from existing one by switch sensor to the spare sensor (Sensor A)(it has 2 sensing probes in temp sensor head) &gt;&gt;Done</p><p>Check several transmitters that ex post to weather to confirm there is no water ingress &gt;&gt; Done</p><p>Normalize and clear all alarm confirmed all activities are cleared. &gt;&gt;Done</p><p><br></p>', '<p><span style="color: rgb(69, 90, 100); font-size: 12px; background-color: rgb(249, 249, 249);">20.45.25.003.3 &gt;&gt; IO card</span></p><p><span style="color: rgb(69, 90, 100); text-wrap-mode: nowrap;">20.45.26.500.3 &gt;&gt; clutch temp element.</span></p><p><span style="color: rgb(69, 90, 100); text-wrap-mode: nowrap; background-color: rgb(249, 249, 249);">20.45.26.451.3 &gt;&gt;&nbsp;</span><span style="color: rgb(69, 90, 100); text-wrap-mode: nowrap;"></span><span style="background-color: rgb(249, 249, 249); color: rgb(69, 90, 100); font-size: 12px; text-wrap-mode: nowrap;">ACCELEROMETER 2VE-332000 A/B</span></p><p><span style="color: rgb(69, 90, 100); text-wrap-mode: nowrap;"><br></span></p>', '2024-12-09 08:41:43', '2024-12-10 17:24:09', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\GBS.Turbine-Tech', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2TE-332870A', 'GBS-2TE-332870A', 'TEMPERATURE ELEMENT', NULL, NULL, 'TEMPERATURE ELEMENT', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
